(function(){
const state={page:"rules",profiles:[],preview:null,routing:{enabled:false,listen:"127.0.0.1",port:16080,default_action:"block",default_profile_id:"",rules:[]},runtime:null,refresh:null,health:null,configured:false,ruleEditorOpen:false,editingRuleIndex:null,ruleEditorAction:"profile",subscriptionTab:"update",subscriptionProfileID:"",networkTab:"connections",dnsTab:"core",dns:{enabled:false,listen:"127.0.0.1",port:5353,auto_provider:true,provider_id:"",servers:[],hosts:[],blocklists:[],rules:[]},dnsStatus:null,dnsStats:null,dnsBlocklists:{sources:[],blocked:[],allowed:[],settings:{autoUpdate:false,updateTime:"04:30",iface:""},error:""},smartDNS:{config:{enabled:false,listen_host:"127.0.0.1",listen_port:5354,cache_size:0,upstreams:[],rules:[],domain_sets:[]},status:{enabled:false,running:false},error:""},observatorySettings:{probe_interval_seconds:30},geodata:{ready:false,assets:[],error:""},watchlist:{ready:false,path:"",targets:0,keys:0,partial:false,excluded_patterns:0,error:""},l7Settings:{enabled:false,http:true,tls:true,quic:true},healthMonitor:null,healthSettings:{enabled:true,interval_seconds:30,timeout_seconds:4,fail_threshold:2,recover_threshold:2},events:[]};
let observatoryPollTimer=null;
let eventStream=null;
let observatoryPingAbort=null;
const titles={rules:["ПРАВИЛА","Правила","Порядок обработки трафика · первое совпадение сверху вниз"],network:["СЕТЬ","Сеть","Управление Xray и отдельными прокси-подключениями"],dns:["DNS","DNS","DNS-настройки и текущее состояние"],hydra:["HYDRA","Hydra","Профили, серверные пулы и балансировщики"],settings:["НАСТРОЙКИ","Настройки","Управление Xray, применение конфигурации и журнал"],info:["ИНФОРМАЦИЯ","Инфо","Версия, API и состояние компонентов"],servers:["HYDRA · СЕРВЕРЫ","Выбор серверов","Ручной выбор узлов и исключения для профиля"]};
const $=id=>document.getElementById(id);
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function toast(msg,error){const el=$("toast");el.textContent=msg;el.className="toast show"+(error?" error":"");setTimeout(()=>el.className="toast",3200);}
async function api(path,method,body){const opt={method:method||"GET",headers:{}};if(body!==undefined){opt.headers["Content-Type"]="application/json";opt.body=JSON.stringify(body);}const r=await fetch(path,opt);let data={};try{data=await r.json();}catch(e){}if(!r.ok)throw new Error(data.error||data.message||("HTTP "+r.status));return data;}
function profileEndpoint(p){return (p.listen||"127.0.0.1")+":"+p.port;}
function stopEventStream(){if(eventStream){eventStream.close();eventStream=null;}}
function startEventStream(){if(eventStream||!window.EventSource)return;const last=(state.events||[]).reduce((n,e)=>Math.max(n,Number(e.id)||0),0);eventStream=new EventSource('/v1/events/stream?after_id='+last);eventStream.addEventListener('message',e=>{try{const item=JSON.parse(e.data);if(!(state.events||[]).some(old=>old.id===item.id)){state.events=[...(state.events||[]),item].slice(-50);if(state.page==='settings')render();}}catch(_){}});}
function setPage(page){state.page=page;if(page==="settings")startEventStream();else stopEventStream();if(page==="dns"){loadDNS().then(()=>{if(state.page==="dns")render();});}document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===page));const t=titles[page]||titles.connect;$("pageEyebrow").textContent=t[0];$("pageTitle").textContent=t[1];$("pageDescription").textContent=t[2];$("sidebar").classList.remove("open");render();}
function copyText(text){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(()=>toast("Скопировано")).catch(()=>toast("Не удалось скопировать",true));}else toast(text);}
function profileCards(){if(!state.profiles.length)return '<div class="empty">Профили пока не добавлены. Создайте первый профиль во вкладке «Профили».</div>';return '<div class="profile-list">'+state.profiles.map(p=>'<article class="card profile-card"><div class="profile-main"><div class="profile-avatar">'+esc((p.id||"?").slice(0,1).toUpperCase())+'</div><div><div class="profile-name">'+esc(p.id)+'</div><div class="profile-meta">'+esc(p.source_id)+' · '+(p.enabled?'<span class="pill good">Включён</span>':'<span class="pill">Отключён</span>')+'</div><div class="profile-endpoint">socks5://'+esc(profileEndpoint(p))+'</div></div></div><div class="runtime-actions"><button class="copy-btn" data-copy="socks5://'+esc(profileEndpoint(p))+'">Копировать</button><button class="copy-btn" data-preview-servers="'+esc(p.id)+'">Серверы</button><button class="button danger" data-delete-profile="'+esc(p.id)+'">Удалить</button></div></article>').join("")+'</div>';}
function overview(){const running=!!(state.runtime&&state.runtime.running),configured=!!(state.runtime&&state.runtime.configured),rt=running?"Работает":configured?"Готов к запуску":"Не настроен";const r=state.routing;const shared=r.enabled?(r.listen||"127.0.0.1")+":"+r.port:"Не включён";return '<div class="grid stats-grid"><article class="card stat-card"><div class="stat-label">СОСТОЯНИЕ RUNTIME</div><div class="stat-value">'+rt+'</div><div class="stat-hint">'+(running?"Xray запущен":configured?"Конфигурация подготовлена":"Нет активной конфигурации")+'</div></article><article class="card stat-card"><div class="stat-label">ПРОФИЛИ</div><div class="stat-value">'+state.profiles.length+'</div><div class="stat-hint">Независимые пулы и балансировщики</div></article><article class="card stat-card"><div class="stat-label">ОБЩИЙ SOCKS5</div><div class="stat-value">'+(r.enabled?"Включён":"Выключен")+'</div><div class="stat-hint">'+esc(shared)+'</div></article><article class="card stat-card"><div class="stat-label">АВТООБНОВЛЕНИЕ</div><div class="stat-value">'+(state.refresh&&state.refresh.enabled?"Включено":"Выключено")+'</div><div class="stat-hint">'+(state.refresh&&state.refresh.interval_seconds?state.refresh.interval_seconds+" сек.":"Ручное обновление")+'</div></article></div><div class="grid two-col"><div class="grid"><article class="card shared-card"><div class="shared-head"><div class="shared-title"><span class="symbol">⌘</span>Общий SOCKS5</div><span class="tag">ROUTER</span></div><div class="endpoint">'+esc(shared)+' <small>LOCAL</small></div><div class="copy-row"><span class="muted">'+(r.enabled?"Трафик распределяется по правилам маршрутизации":"Включите общий вход в разделе маршрутизации")+'</span>'+(r.enabled?'<button class="copy-btn" data-copy="socks5://'+esc((r.listen||"127.0.0.1")+":"+r.port)+'">Копировать</button>':'<button class="copy-btn" data-page="routing">Настроить</button>')+'</div></article><div><div class="section-title"><h2>Профили подключений</h2><button class="copy-btn" data-page="hydra">Все профили →</button></div>'+profileCards()+'</div></div><div class="grid"><article class="card"><div class="section-title"><h2>Управление runtime</h2><span class="pill '+(running?"good":"")+'">'+(running?"ONLINE":"OFFLINE")+'</span></div><div class="runtime-actions"><button class="button primary" data-runtime="start" '+(!configured||running?"disabled":"")+'>▶ Запустить</button><button class="button danger" data-runtime="stop" '+(!running?"disabled":"")+'>■ Остановить</button></div><div class="muted-note" style="margin-top:14px">Core управляет только собственным процессом Xray. Системные маршруты, DNS и firewall не меняются.</div></article><article class="card"><div class="section-title"><h2>Последнее обновление</h2><span class="pill">'+(state.refresh&&state.refresh.running?"Выполняется":"Готово")+'</span></div><div class="info-list"><div class="info-row"><span>Последняя попытка</span><b>'+esc(formatTime(state.refresh&&state.refresh.last_attempt))+'</b></div><div class="info-row"><span>Последний успех</span><b>'+esc(formatTime(state.refresh&&state.refresh.last_success))+'</b></div></div><button class="button secondary" style="margin-top:14px;width:100%" data-refresh>↻ Обновить подписки</button></article></div></div>';}
function formatTime(v){if(!v)return "—";try{return new Date(v).toLocaleString();}catch(e){return "—";}}
function profilesPage(){return '<div class="grid two-col"><div><div class="section-title"><h2>Сохранённые профили</h2><small>'+state.profiles.length+' шт.</small></div>'+profileCards()+'</div><article class="card"><div class="section-title"><h2>Добавить профиль</h2><span class="tag">NEW</span></div><form id="profileForm" class="form-grid"><div class="field"><label>ID профиля</label><input name="id" required maxlength="32" pattern="[A-Za-z0-9_-]+" placeholder="foreign"></div><div class="field"><label>ID источника</label><input name="source_id" required maxlength="64" pattern="[A-Za-z0-9_.-]+" placeholder="providerA"></div><div class="field"><label>Порт SOCKS5</label><input name="port" type="number" min="1024" max="65535" value="16090" required></div><div class="field"><label>Стратегия</label><select name="strategy"><option value="leastPing">Least Ping</option><option value="roundRobin">Round Robin</option><option value="random">Random</option></select></div><div class="field full"><label>Ссылка или список ссылок (по одной на строку)</label><textarea name="links" required placeholder="vless://…"></textarea></div><label class="checkline field full"><input name="enabled" type="checkbox" checked> Включить профиль</label><div class="form-actions field full"><button class="button primary" type="submit">Сохранить профиль</button></div></form><div class="muted-note" style="margin-top:14px">Данные подписки хранятся в зашифрованном хранилище. После сохранения выполните обновление, чтобы подготовить конфигурацию Xray.</div></article></div>';}
function targetSelect(selected){return '<select class="rule-profile"><option value="">— выберите профиль —</option>'+state.profiles.filter(p=>p.enabled).map(p=>'<option value="'+esc(p.id)+'" '+(p.id===selected?"selected":"")+'>'+esc(p.id)+'</option>').join("")+'</select>';}
function rulesHtml(){if(!state.routing.rules||!state.routing.rules.length)return '<div class="rules-empty">Правил пока нет. Добавьте первое правило.</div>';return '<div class="rule-list" id="ruleList">'+state.routing.rules.map((r,i)=>{const action=r.action==="direct"?"DIRECT":r.action==="block"?"BLOCK":(r.profile_id||"Выберите подключение");const match=r.match_type==="ip"?"IP / CIDR":"Домены";return '<article class="rule-card" data-rule="'+i+'"><div class="rule-head"><div class="rule-title-wrap"><button type="button" class="rule-drag-handle" draggable="true" data-drag-rule="'+i+'" aria-label="Перетащить правило" title="Перетащить для изменения порядка">⠿</button><span class="rule-status '+(r.enabled?'is-enabled':'')+'" aria-label="'+(r.enabled?'Включено':'Отключено')+'"></span><label class="rule-enable"><input class="rule-enabled" data-rule-enabled="'+i+'" type="checkbox" '+(r.enabled?"checked":"")+'><span class="rule-name-text">'+esc(r.name||"Правило "+(i+1))+'</span></label><span class="rule-route-badge '+(r.action==='direct'?'direct':r.action==='block'?'blocked':'')+'">'+esc(action)+'</span><span class="rule-kind">'+match+'</span></div><div class="rule-actions"><button type="button" class="rule-icon-btn" data-edit-rule="'+i+'" title="Изменить правило" aria-label="Изменить">✎</button><button type="button" class="rule-icon-btn" data-duplicate-rule="'+i+'" title="Создать копию" aria-label="Копировать">⧉</button><button type="button" class="rule-icon-btn delete" data-index="'+i+'" title="Удалить правило" aria-label="Удалить">▢</button></div></div><div class="rule-summary">'+esc(match)+' · '+(r.values||[]).length+' знач. · '+esc((r.values||[]).slice(0,3).join(', '))+'</div></article>';}).join("")+'</div>';}
function watchlistCard(){const w=state.watchlist||{},label=w.ready?'Активен':'Ожидает';return '<article class="card geodata-card"><div class="section-title"><h2>Watchlist MATCH / DUMP</h2><span class="pill '+(w.ready?'good':'')+'">'+label+'</span></div><div class="info-list"><div class="info-row"><span>Целей</span><b>'+Number(w.targets||0)+'</b></div><div class="info-row"><span>Ключей доменов</span><b>'+Number(w.keys||0)+'</b></div><div class="info-row"><span>Локальный Unix socket</span><b>'+(w.ready?'0600':'Не создан')+'</b></div></div>'+(w.path?'<div class="muted-note" style="margin-top:8px">'+esc(w.path)+'</div>':'')+(w.partial?'<div class="muted-note" style="margin-top:8px">Частичный список: '+Number(w.excluded_patterns||0)+' невычисляемых шаблонов исключено. MATCH/DUMP перечисляет конкретные домены и GeoSite Domain/Full; keyword/regexp и GeoSite Plain/Regex не раскрываются в ключи.</div>':'')+(w.error?'<div class="muted-note">'+esc(w.error)+'</div>':'')+'</article>';}

function geodataCard(){const g=state.geodata||{},assets=g.assets||[];const label=g.ready?'Доступны':'Не готовы';const u=g.update||{};const updateNote=u.error?'Состояние обновления: '+esc(u.error):u.pending?'Восстановление требуется (этап: '+esc(u.phase||'неизвестен')+')':u.ready?'Управляемая версия: '+esc(u.current||'—'):u.present?'Управляемое хранилище ещё не готово':'Автоматическое обновление баз пока не настроено';const rows=assets.map(a=>'<div class="info-row"><span>'+esc(a.name==='geoip.dat'?'GeoIP':'GeoSite')+'</span><b>'+(a.available?'✓ '+(a.size?Math.round(a.size/1024/1024*10)/10+' МБ':'Доступен'):'Нет файла')+'</b></div>').join('');return '<article class="card geodata-card"><div class="section-title"><h2>Геоданные Xray</h2><span class="pill '+(g.ready?'good':'')+'">'+label+'</span></div><div class="info-list">'+(rows||'<div class="info-row"><span>GeoIP / GeoSite</span><b>Проверка недоступна</b></div>')+'</div><div class="muted-note" style="margin-top:10px">'+updateNote+'</div><div class="muted-note" style="margin-top:10px">Геоданные используются правилами geoip: и geosite:. Их наличие проверяется отдельно от сохранения правил.</div>'+(g.error?'<div class="muted-note">'+esc(g.error)+'</div>':'')+'<details class="geodata-update" style="margin-top:12px"><summary>Проверка и обновление баз GeoIP / GeoSite</summary><form id="geodataUpdateForm" class="form-grid" style="margin-top:12px"><div class="field full"><label>GeoIP HTTPS URL</label><input name="geoip_url" type="url" required placeholder="https://…/geoip.dat"></div><div class="field full"><label>GeoIP SHA-256 (64 символа)</label><input name="geoip_sha256" pattern="[A-Fa-f0-9]{64}" minlength="64" maxlength="64" required autocomplete="off"></div><div class="field full"><label>GeoSite HTTPS URL</label><input name="geosite_url" type="url" required placeholder="https://…/geosite.dat"></div><div class="field full"><label>GeoSite SHA-256 (64 символа)</label><input name="geosite_sha256" pattern="[A-Fa-f0-9]{64}" minlength="64" maxlength="64" required autocomplete="off"></div><div class="field full"><button type="submit" class="button secondary" data-geodata-action="preflight">Проверить без применения</button> <button type="submit" class="button primary" data-geodata-action="activate" '+(!u.ready||u.pending||!state.runtime?.running?'disabled':'')+'>Применить с откатом</button></div></form><div class="muted-note">Для применения Xray должен использовать управляемую версию баз. Обновление перезапускает Xray; при ошибке выполняется откат. Источники и контрольные суммы вводятся вручную.</div></details></article>';}

function ruleEditorHtml(){if(!state.ruleEditorOpen)return '';const editing=Number.isInteger(state.editingRuleIndex)?state.routing.rules[state.editingRuleIndex]:null;const r=editing||{name:"",match_type:"domain",values:[],action:state.ruleEditorAction||"profile",profile_id:""};return '<article class="card"><div class="section-title"><h2>'+(editing?'Редактировать правило':'Новое правило')+'</h2><button type="button" class="copy-btn" id="cancelRuleEditor">Закрыть</button></div><form id="ruleEditorForm" class="form-grid"><div class="field"><label>Название правила</label><input name="name" required maxlength="80" value="'+esc(r.name)+'" placeholder="YouTube"></div><div class="field"><label>Тип совпадения</label><select name="match_type"><option value="domain" '+(r.match_type==='domain'?'selected':'')+'>Домен</option><option value="ip" '+(r.match_type==='ip'?'selected':'')+'>IP / CIDR</option></select></div><div class="field full"><label>Домены или IP — по одному на строку</label><textarea name="values" required class="rule-values" placeholder="geosite:youtube&#10;domain:youtube.com">'+esc((r.values||[]).join("\n"))+'</textarea><div class="muted-note">Домен: domain:example.com, geosite:youtube, keyword:example. IP: адрес, CIDR или geoip:ru. Внешний список: ext:geosite.dat:tag. Доступность GeoIP/GeoSite отображается выше; Xray проверит выбранные теги при применении.</div></div><div class="field"><label>Действие</label><select name="action" id="ruleEditorAction"><option value="profile" '+(r.action==='profile'?'selected':'')+'>Профиль</option><option value="direct" '+(r.action==='direct'?'selected':'')+'>DIRECT</option><option value="block" '+(r.action==='block'?'selected':'')+'>BLOCK</option></select></div><div class="field" id="ruleProfileField"><label>Профиль назначения</label>'+targetSelect(r.profile_id)+'</div><div class="form-actions field full"><button class="button primary" type="submit">'+(editing?'Сохранить правило':'Добавить правило')+'</button></div></form></article>';}
function connectPage(){const running=!!(state.runtime&&state.runtime.running);const shared=state.routing.enabled?(state.routing.listen||"127.0.0.1")+":"+state.routing.port:"Выключен";return '<div class="grid stats-grid"><article class="card stat-card"><div class="stat-label">XRAY RUNTIME</div><div class="stat-value">'+(running?"Работает":"Остановлен")+'</div><div class="stat-hint">Состояние управляемого процесса</div></article><article class="card stat-card"><div class="stat-label">ПРОФИЛИ</div><div class="stat-value">'+state.profiles.length+'</div><div class="stat-hint">Изолированные серверные пулы</div></article><article class="card stat-card"><div class="stat-label">ОБЩИЙ SOCKS5</div><div class="stat-value">'+(state.routing.enabled?"Включён":"Выключен")+'</div><div class="stat-hint">'+esc(shared)+'</div></article><article class="card stat-card"><div class="stat-label">ПОДКЛЮЧЕНИЯ</div><div class="stat-value">'+state.profiles.filter(p=>p.enabled).length+'</div><div class="stat-hint">Активные профили</div></article></div>'+profilesPage();}
function networkTabs(){return '<div class="network-tabs"><button class="network-tab '+(state.networkTab==='connections'?'active':'')+'" data-network-tab="connections">Подключения</button><button class="network-tab '+(state.networkTab==='monitor'?'active':'')+'" data-network-tab="monitor">Монитор</button><button class="network-tab '+(state.networkTab==='terminal'?'active':'')+'" data-network-tab="terminal">Терминал</button></div>';}
function connectionCards(){if(!state.profiles.length)return '<div class="empty network-empty"><div class="network-empty-icon">⚡</div><b>Подключения пока не добавлены</b><p>Добавьте подписку или ссылку на прокси, чтобы создать первое подключение.</p><button class="network-add network-add-empty" id="openConnectionModal">＋ Добавить подключение</button></div>';return '<div class="connection-cards">'+state.profiles.map(p=>'<article class="card connection-card"><div class="connection-card-head"><div class="connection-card-title"><button type="button" class="runtime-toggle '+(p.enabled?'on':'')+'" data-profile-toggle="'+esc(p.id)+'" aria-label="'+(p.enabled?'Отключить':'Включить')+' '+esc(connectionName(p))+'"><span></span></button><div><b>'+esc(connectionName(p))+'</b></div></div><div class="connection-card-actions"><button class="network-icon-btn" data-connection-menu="'+esc(p.id)+'" title="Настройки подключения" aria-label="Настройки">⚙</button><button class="network-icon-btn danger" data-delete-profile="'+esc(p.id)+'" title="Удалить подключение" aria-label="Удалить">▤</button></div></div><div class="connection-tags"><span class="tag">xRay</span><span class="tag">SOCKS5</span></div><div class="connection-card-foot"><span class="connection-endpoint">'+esc(p.strategy==='leastPing'?'Авто · наименьшая задержка':p.strategy==='roundRobin'?'По кругу':p.strategy==='random'?'Случайный':'Авто')+'</span><button class="copy-btn" data-profile-test="'+esc(p.id)+'">◉ Speed test</button><span class="connection-test-result" id="profileTest-'+esc(p.id)+'">—</span></div></article>').join('')+'</div>';}
function connectionSettingsMenu(p){const d=p.dpi_bypass||{};const dpiCount=[d.noise_traffic,d.tls_fragmentation,d.random_tls_fingerprint].filter(Boolean).length;const strategy=p.strategy==='leastPing'?'Наименьшая задержка':p.strategy==='roundRobin'?'По кругу':p.strategy==='random'?'Случайный сервер':'Наименьшая задержка';return `<div class="connection-settings-backdrop" data-close-connection-menu="${esc(p.id)}"></div><div class="connection-settings-menu" role="menu" aria-label="Настройки подключения"><button type="button" class="connection-menu-item" data-menu-servers="${esc(p.id)}"><span class="connection-menu-icon">▤</span><span>Серверы...</span><span class="connection-menu-chevron">›</span></button>${p.mux_compatible?`<button type="button" class="connection-menu-item" data-menu-mux="${esc(p.id)}"><span class="connection-menu-icon">⇄</span><span>Мультиплексирование</span><span class="connection-menu-value">${p.mux_enabled?"Включено":"Выключено"}</span></button>`:""}<button type="button" class="connection-menu-item" data-menu-dpi="${esc(p.id)}"><span class="connection-menu-icon">⬡</span><span>Обход DPI</span><span class="connection-menu-value">${dpiCount} из 3</span><span class="connection-menu-chevron">›</span></button><button type="button" class="connection-menu-item" data-menu-balance="${esc(p.id)}"><span class="connection-menu-icon">♧</span><span>Балансировка</span><span class="connection-menu-value">${esc(strategy)}</span><span class="connection-menu-chevron">›</span></button><button type="button" class="connection-menu-item" data-menu-interface="${esc(p.id)}"><span class="connection-menu-icon">↗</span><span>Исходящий интерфейс</span><span class="connection-menu-value">${esc(p.outbound_interface||'авто')}</span><span class="connection-menu-chevron">›</span></button></div>`;}
function openConnectionSettingsMenu(id,button){const p=state.profiles.find(x=>x.id===id);if(!p)return;document.querySelectorAll('.connection-settings-menu,.connection-settings-backdrop,.connection-option-panel').forEach(x=>x.remove());const card=button.closest('.connection-card');card.insertAdjacentHTML('beforeend',connectionSettingsMenu(p));const menu=card.querySelector('.connection-settings-menu');menu.querySelector('[data-menu-servers]').onclick=()=>{menu.remove();card.querySelector('.connection-settings-backdrop')?.remove();openServerPicker(id);};menu.querySelector('[data-menu-mux]')?.addEventListener('click',()=>saveConnectionOptions(id,{mux_enabled:!p.mux_enabled}));menu.querySelector('[data-menu-balance]').onclick=()=>openProfileOptionPanel(id,'balance',card);menu.querySelector('[data-menu-dpi]').onclick=()=>openProfileOptionPanel(id,'dpi',card);menu.querySelector('[data-menu-interface]').onclick=()=>openProfileOptionPanel(id,'interface',card);card.querySelector('.connection-settings-backdrop').onclick=()=>{menu.remove();card.querySelector('.connection-settings-backdrop')?.remove();};}
async function saveConnectionOptions(id,patch){try{await api('/v1/profiles','PUT',{id,...patch});document.querySelectorAll('.connection-settings-menu,.connection-settings-backdrop,.connection-option-panel').forEach(x=>x.remove());toast('Настройки подключения сохранены');await loadData();}catch(err){toast(err.message,true);}}
async function openProfileOptionPanel(id,kind,card){const p=state.profiles.find(x=>x.id===id);if(!p)return;card.querySelector('.connection-settings-menu')?.remove();const dpi=p.dpi_bypass||{};let body='';if(kind==='dpi'){body=`<div class="connection-option-title">Обход DPI</div><label class="connection-option-check"><input type="checkbox" name="noise_traffic" ${dpi.noise_traffic?'checked':''}>Шумовой трафик</label><label class="connection-option-check"><input type="checkbox" name="tls_fragmentation" ${dpi.tls_fragmentation?'checked':''}>Фрагментация TLS</label><label class="connection-option-check"><input type="checkbox" name="random_tls_fingerprint" ${dpi.random_tls_fingerprint?'checked':''}>Случайный отпечаток TLS</label><div class="connection-option-actions"><button class="button secondary" data-option-cancel>Отмена</button><button class="button primary" data-option-save>Сохранить</button></div>`;}else if(kind==='balance'){const current=p.strategy||'leastPing';body=`<div class="connection-option-title">Балансировка</div><label class="connection-option-radio"><input type="radio" name="strategy" value="leastPing" ${current==='leastPing'?'checked':''}>Наименьшая задержка</label><label class="connection-option-radio"><input type="radio" name="strategy" value="random" ${current==='random'?'checked':''}>Случайный сервер</label><label class="connection-option-radio"><input type="radio" name="strategy" value="roundRobin" ${current==='roundRobin'?'checked':''}>По кругу</label>`;}else{body=`<div class="connection-option-title">Исходящий интерфейс</div><input class="connection-interface-search" type="search" placeholder="Поиск" aria-label="Поиск интерфейсов"><div class="connection-interface-tabs"><button type="button" class="active" data-iface-category="VPN">VPN <span></span></button><button type="button" data-iface-category="Интернет">Интернет <span></span></button><button type="button" data-iface-category="Остальное">Остальное <span></span></button></div><div class="connection-interface-list" aria-live="polite">Загрузка интерфейсов…</div>`;}card.insertAdjacentHTML('beforeend',`<div class="connection-settings-backdrop" data-option-backdrop></div><section class="connection-option-panel" role="dialog" aria-label="Настройки подключения">${body}</section>`);const panel=card.querySelector('.connection-option-panel');const close=()=>{panel.remove();card.querySelector('[data-option-backdrop]')?.remove();};panel.querySelector('[data-option-cancel]')?.addEventListener('click',close);card.querySelector('[data-option-backdrop]').onclick=close;if(kind==='dpi'){panel.querySelector('[data-option-save]').onclick=()=>{const read=n=>panel.querySelector(`[name="${n}"]`).checked;saveConnectionOptions(id,{dpi_bypass:{noise_traffic:read('noise_traffic'),tls_fragmentation:read('tls_fragmentation'),random_tls_fingerprint:read('random_tls_fingerprint')}});};}else if(kind==='balance'){panel.querySelectorAll('[name="strategy"]').forEach(el=>el.onchange=()=>saveConnectionOptions(id,{strategy:el.value}));}else{let interfaces=[];let category='VPN';const list=panel.querySelector('.connection-interface-list');const search=panel.querySelector('.connection-interface-search');const renderList=()=>{const q=search.value.trim().toLowerCase();const rows=interfaces.filter(x=>x.category===category&&(!q||x.name.toLowerCase().includes(q)));const auto=`<button type="button" class="connection-interface-choice ${!p.outbound_interface?'selected':''}" data-interface-value=""><span class="interface-dot good"></span><span><b>Авто — системная маршрутизация</b></span>${!p.outbound_interface?'✓':''}</button>`;list.innerHTML=auto+rows.map(x=>`<button type="button" class="connection-interface-choice ${p.outbound_interface===x.name?'selected':''}" data-interface-value="${esc(x.name)}"><span class="interface-dot ${x.up?'good':'down'}"></span><span><b>${esc(x.name)}</b><small>${x.up?'Активен':'Неактивен'}</small></span>${p.outbound_interface===x.name?'✓':''}</button>`).join('')+(rows.length?'':'<div class="muted-note">Нет интерфейсов в этой категории</div>');list.querySelectorAll('[data-interface-value]').forEach(b=>b.onclick=()=>saveConnectionOptions(id,{outbound_interface:b.dataset.interfaceValue}));};try{const data=await api('/v1/interfaces');interfaces=data.interfaces||[];panel.querySelectorAll('[data-iface-category]').forEach(b=>{b.querySelector('span').textContent=interfaces.filter(x=>x.category===b.dataset.ifaceCategory).length;b.onclick=()=>{category=b.dataset.ifaceCategory;panel.querySelectorAll('[data-iface-category]').forEach(x=>x.classList.toggle('active',x===b));renderList();};});search.oninput=renderList;renderList();}catch(err){list.textContent='Не удалось получить список интерфейсов: '+err.message;}}}

function connectionNames(){try{return JSON.parse(localStorage.getItem('hr-connection-names')||'{}')}catch(e){return {};}}
function connectionName(p){return connectionNames()[p.id]||p.name||p.id;}
function connectionModal(){return '<div class="connection-modal-backdrop" id="connectionModal" role="presentation"><section class="card connection-modal" role="dialog" aria-modal="true" aria-labelledby="connectionModalTitle"><div class="section-title"><h2 id="connectionModalTitle">Новое подключение</h2><button type="button" class="copy-btn" id="closeConnectionModal" aria-label="Закрыть">✕</button></div><form id="connectionForm" class="form-grid"><div class="field full"><label for="connectionName">Название подключения</label><input id="connectionName" name="name" required maxlength="80" placeholder="International"></div><div class="field full"><label for="connectionUrl">Ссылка на подписку</label><textarea id="connectionUrl" name="url" required rows="3" placeholder="https://example.com/subscription"></textarea></div><div class="form-actions field full"><button type="button" class="button secondary" id="cancelConnection">Отмена</button><button type="submit" class="button primary">Создать подключение</button></div></form></section></div>';}
function openConnectionModal(){const old=$('connectionModal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend',connectionModal());const modal=$('connectionModal');modal.classList.add('open');const close=()=>modal&&modal.remove();$('closeConnectionModal').onclick=close;$('cancelConnection').onclick=close;modal.addEventListener('click',e=>{if(e.target===modal)close();});$('connectionName').focus();$('connectionForm').onsubmit=saveConnection;}
async function saveConnection(e){e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name')||'').trim(),url=String(f.get('url')||'').trim();if(!name||!url)return;const map={'А':'A','Б':'B','В':'V','Г':'G','Д':'D','Е':'E','Ё':'E','Ж':'Zh','З':'Z','И':'I','Й':'I','К':'K','Л':'L','М':'M','Н':'N','О':'O','П':'P','Р':'R','С':'S','Т':'T','У':'U','Ф':'F','Х':'Kh','Ц':'Ts','Ч':'Ch','Ш':'Sh','Щ':'Shch','Ъ':'','Ы':'Y','Ь':'','Э':'E','Ю':'Yu','Я':'Ya','а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e','ж':'zh','з':'z','и':'i','й':'i','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts','ч':'ch','ш':'sh','щ':'shch','ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'};const slug=name.split('').map(ch=>map[ch]??ch).join('').replace(/[^A-Za-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,24)||'connection';let id=slug,idx=2;while(state.profiles.some(p=>p.id===id)){id=(slug.slice(0,Math.max(1,31-String(idx).length))+'-'+idx++).slice(0,32);}const source='sub-'+id.slice(0,58);const used=state.profiles.map(p=>Number(p.port)||0);let port=16090;while(used.includes(port)&&port<65535)port++;const body={id,source_id:source,enabled:true,port,strategy:'leastPing',subscription_url:url};const submit=e.currentTarget.querySelector('button[type="submit"]');submit.disabled=true;try{await api('/v1/profiles','POST',body);const names=connectionNames();names[id]=name;localStorage.setItem('hr-connection-names',JSON.stringify(names));$('connectionModal')?.remove();toast('Подключение создано');await api('/v1/profiles/refresh','POST',{});await loadData();}catch(err){submit.disabled=false;toast(err.message,true);}}
function networkConnections(){const running=!!(state.runtime&&state.runtime.running),configured=!!(state.runtime&&state.runtime.configured);return '<div class="network-runtime"><div class="network-runtime-left"><button type="button" class="runtime-toggle '+(running?'on':'')+'" data-runtime="'+(running?'stop':'start')+'" '+(!running&&!configured?'disabled':'')+' aria-label="'+(running?'Остановить Xray':'Запустить Xray')+'"><span></span></button><b>xRay</b><span class="pill '+(running?'good':'')+'">'+(running?'Работает':configured?'Готов к запуску':'Остановлен')+'</span><button class="network-icon-btn" data-refresh title="Обновить подписки и профили">↻</button><button class="network-icon-btn" data-page="settings" title="Настройки Xray">⚙</button></div></div>'+connectionCards()+'<button class="network-add" id="openConnectionModal">＋ Добавить подключение</button><div class="network-footer-note">Каждое подключение управляет только собственным профилем и SOCKS5-входом HydraRoute Core.</div>'+connectionModal();}
function profileSettingsModal(p){return '<div class="connection-modal-backdrop open" id="profileSettingsModal"><section class="card connection-modal" role="dialog" aria-modal="true"><div class="section-title"><h2>Настройки · '+esc(connectionName(p))+'</h2><button type="button" class="copy-btn" id="closeProfileSettings">✕</button></div><form id="profileSettingsForm" class="form-grid"><input type="hidden" name="id" value="'+esc(p.id)+'"><div class="field full"><label>Название подключения</label><input name="name" maxlength="80" required value="'+esc(connectionName(p))+'"></div><div class="field"><label>Порт SOCKS5</label><input name="port" type="number" min="1024" max="65535" required value="'+Number(p.port)+'"></div><div class="field"><label>Балансировщик</label><select name="strategy"><option value="leastPing" '+(p.strategy==='leastPing'?'selected':'')+'>Наименьший пинг</option><option value="roundRobin" '+(p.strategy==='roundRobin'?'selected':'')+'>По кругу</option><option value="random" '+(p.strategy==='random'?'selected':'')+'>Случайный</option></select></div><div class="field full"><label>Режим подключения</label><input value="xRay · SOCKS5" disabled></div><div class="form-actions field full"><button type="button" class="button secondary" id="cancelProfileSettings">Отмена</button><button type="submit" class="button primary">Сохранить</button></div></form></section></div>';}
async function openProfileSettings(id){const p=state.profiles.find(x=>x.id===id);if(!p)return;document.getElementById('profileSettingsModal')?.remove();document.body.insertAdjacentHTML('beforeend',profileSettingsModal(p));const close=()=>document.getElementById('profileSettingsModal')?.remove();$('closeProfileSettings').onclick=close;$('cancelProfileSettings').onclick=close;$('profileSettingsModal').addEventListener('click',e=>{if(e.target.id==='profileSettingsModal')close();});$('profileSettingsForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={id,port:Number(f.get('port')),strategy:String(f.get('strategy'))};const save=e.currentTarget.querySelector('button[type="submit"]');save.disabled=true;try{await api('/v1/profiles','PUT',body);const names=connectionNames();names[id]=String(f.get('name')).trim();localStorage.setItem('hr-connection-names',JSON.stringify(names));close();toast('Настройки подключения сохранены');await loadData();}catch(err){save.disabled=false;toast(err.message,true);}};}
async function toggleProfile(id,enabled){const p=state.profiles.find(x=>x.id===id);if(!p)return;try{await api('/v1/profiles','PUT',{id,enabled});toast(enabled?'Подключение включено':'Подключение отключено');await loadData();}catch(err){toast(err.message,true);}}
async function testProfile(id){const out=$('profileTest-'+id);if(out)out.textContent='Проверка…';try{const r=await api('/v1/profiles/test','POST',{id});if(out)out.textContent=r.status==='online'?'● '+r.latency_ms+' мс':'Недоступен';toast(r.status==='online'?'Подключение доступно · '+r.latency_ms+' мс':'Подключение не отвечает',r.status!=='online');}catch(err){if(out)out.textContent='Ошибка';toast(err.message,true);}}

function networkMonitor(){const r=state.routing,run=state.runtime||{},ref=state.refresh||{};return '<div class="grid stats-grid"><article class="card stat-card"><div class="stat-label">XRAY</div><div class="stat-value">'+(run.running?'Работает':'Остановлен')+'</div><div class="stat-hint">'+(run.configured?'Конфигурация подготовлена':'Конфигурация не подготовлена')+'</div></article><article class="card stat-card"><div class="stat-label">ПРОФИЛИ</div><div class="stat-value">'+state.profiles.length+'</div><div class="stat-hint">'+state.profiles.filter(p=>p.enabled).length+' включено</div></article><article class="card stat-card"><div class="stat-label">ОБЩИЙ SOCKS5</div><div class="stat-value">'+(r.enabled?'Включён':'Выключен')+'</div><div class="stat-hint">'+esc((r.listen||'127.0.0.1')+':'+(r.port||16080))+'</div></article><article class="card stat-card"><div class="stat-label">ОБНОВЛЕНИЕ ПОДПИСОК</div><div class="stat-value">'+(ref.running?'Выполняется':'Ожидание')+'</div><div class="stat-hint">'+(ref.interval_seconds?Math.round(ref.interval_seconds/60)+' мин.':'Интервал не задан')+'</div></article></div><article class="card"><div class="section-title"><h2>Состояние подписок</h2><button class="button secondary" data-refresh>↻ Обновить сейчас</button></div><div class="info-list"><div class="info-row"><span>Последняя попытка</span><b>'+esc(formatTime(ref.last_attempt))+'</b></div><div class="info-row"><span>Последнее успешное обновление</span><b>'+esc(formatTime(ref.last_success))+'</b></div><div class="info-row"><span>Ошибки подряд</span><b>'+esc(ref.consecutive_failures||0)+'</b></div><div class="info-row"><span>Последняя ошибка</span><b>'+esc(ref.last_error||'—')+'</b></div></div></article><div class="muted-note" style="margin-top:14px">Монитор показывает состояние самого HydraRoute Core. Системные маршруты, DNS и firewall здесь не изменяются.</div>';}
function networkTerminal(){return '<article class="card"><div class="section-title"><h2>Терминал</h2><span class="tag">CORE</span></div><div class="empty"><b>Интерактивный терминал пока не подключён</b><p>В этой версии панели нет безопасного API для выполнения команд или чтения потокового журнала. Команды и вывод не имитируются.</p></div><div class="muted-note" style="margin-top:14px">Состояние Xray и обновления подписок доступно во вкладке «Монитор».</div></article>';}
function tunnelPage(){return '<div class="network-workspace">'+networkTabs()+(state.networkTab==='monitor'?networkMonitor():state.networkTab==='terminal'?networkTerminal():networkConnections())+'</div>'+(state.preview?serverPickerPage():'');}

function rulesPage(){return '<div class="rules-workspace"><div class="rules-toolbar"><button type="button" class="rules-main-action" id="addRuleButton">＋ Добавить правило</button><div class="rules-toolbar-spacer"></div><button type="button" class="rules-tool-btn" id="exportRules">Экспорт</button><button type="button" class="rules-tool-btn" id="importRules">Импорт</button><button type="button" class="rules-tool-btn" id="rulesHelp">ⓘ Справка</button><button type="button" class="rules-tool-btn save" id="saveRouting">Сохранить</button><input type="file" id="importRulesFile" accept="application/json,.json" hidden></div>'+geodataCard()+watchlistCard()+rulesHtml()+(state.ruleEditorOpen?'<div class="rule-editor-wrap">'+ruleEditorHtml()+'</div>':'')+'<div class="muted-note rules-hint">Перетаскивайте правила за маркер ⠿, чтобы изменить приоритет. Порядок обработки — сверху вниз. Переключатель рядом с названием временно отключает правило. ✎ — редактировать, ⧉ — копировать, ▢ — удалить.</div></div>';}
function deployPage(){const running=!!(state.runtime&&state.runtime.running),configured=!!(state.runtime&&state.runtime.configured);return '<div class="grid two-col"><article class="card"><div class="section-title"><h2>Управление Xray</h2><span class="pill '+(running?"good":"")+'">'+(running?"ONLINE":"OFFLINE")+'</span></div><div class="stat-value">'+(running?"Процесс активен":configured?"Конфигурация подготовлена":"Конфигурация не подготовлена")+'</div><div class="muted-note" style="margin-top:12px">Core управляет только собственным процессом Xray. Системные маршруты, DNS, firewall и сетевые интерфейсы не меняются.</div><div class="runtime-actions" style="margin-top:16px"><button class="button primary" data-runtime="start" '+(!configured||running?"disabled":"")+'>▶ Запустить</button><button class="button danger" data-runtime="stop" '+(!running?"disabled":"")+'>■ Остановить</button></div></article><article class="card"><div class="section-title"><h2>Применение конфигурации</h2><span class="tag">DEPLOY</span></div><div class="info-list"><div class="info-row"><span>Профилей</span><b>'+state.profiles.length+'</b></div><div class="info-row"><span>Общий SOCKS5</span><b>'+(state.routing.enabled?"Включён":"Выключен")+'</b></div><div class="info-row"><span>Правил</span><b>'+(state.routing.rules||[]).length+'</b></div></div><button class="button primary" style="margin-top:16px;width:100%" data-refresh>↻ Обновить профили и подготовить конфигурацию</button></article></div>';}

function serverPickerPage(){
 const p=state.preview;if(!p)return '';
 const statuses=p.observatory||{},echoes=p.echoes||{};
 const visible=p.nodes.filter(n=>!n.filtered);
 const selected=visible.filter(n=>n.picked&&!n.excluded).length;
 const sort=p.sort||{key:null,asc:true};
 const rank=(n,key)=>{const k=JSON.stringify(n.key);if(key==='echo'){const x=echoes[k];if(!x||x.pending)return [2,0];return x.delay?[0,x.delay]:[1,0];}const x=statuses[k];if(!x||x.pending||x.stale||!x.last_try_time)return [2,0];return x.alive?[0,x.delay_ms||0]:[1,0];};
 const sortedVisible=[...visible].sort((a,b)=>{if(!sort.key)return 0;if(sort.key==='name')return (sort.asc?1:-1)*a.name.localeCompare(b.name,'ru');const x=rank(a,sort.key),y=rank(b,sort.key);return (sort.asc?1:-1)*(x[0]-y[0]||x[1]-y[1]);});
 const sortMark=k=>sort.key===k?(sort.asc?' ↑':' ↓'):'';
 const excluded=visible.filter(n=>n.excluded).length;
 const all=visible.length>0&&selected===visible.length;
 const offline=visible.filter(n=>{const s=statuses[JSON.stringify(n.key)];return s&&s.last_try_time&&!s.stale&&!s.alive;});
 const offlineAll=offline.length>0&&offline.every(n=>n.excluded);
 const row=(n,i,hidden=false)=>{const key=JSON.stringify(n.key),st=statuses[key],echo=echoes[key],has=!!(st&&st.last_try_time),ping=echo?(echo.pending?'…':(echo.delay!==undefined?esc(echo.delay)+' ms':'N/A')):'—',delay=st?(st.pending?'…':(has?(st.stale?'устарело':(st.alive?esc(st.delay_ms)+' ms':'offline')):'—')):'—';return '<tr class="subscription-node-row '+(hidden?'filtered-node-row':'')+'" data-node-row="'+i+'"><td><input type="checkbox" class="pick-node" data-index="'+i+'" '+(!hidden&&n.picked&&!n.excluded?'checked':'')+' '+(hidden?'disabled':'')+' aria-label="Учитывать '+esc(n.name)+'"></td><td><span class="node-protocol">'+esc(n.protocol||'proxy')+'</span></td><td class="subscription-server-name"><b><span class="subscription-server-flag" aria-hidden="true">'+serverCountryFlag(n.name)+'</span>'+esc(n.name)+'</b><small>'+esc(n.key.source)+(n.key.nth?' · дубликат '+(n.key.nth+1):'')+'</small></td><td class="node-ping">'+(ping==='—'?'<span class="muted">—</span>':ping==='N/A'?'<span class="muted" title="Нет ICMP-ответа или ping недоступен">N/A</span>':ping==='…'?'<span class="muted">…</span>':'<span class="good">'+ping+'</span>')+'</td><td class="node-delay">'+(delay==='offline'?'<span class="bad">● offline</span>':delay==='устарело'?'<span class="muted" title="Последнее измерение сохранено, но Xray не подтвердил его актуальность">устарело</span>':delay==='—'?'<span class="muted">—</span>':delay==='…'?'<span class="muted">…</span>':'<span class="good">'+delay+'</span>')+'</td></tr>';};
 const rows=sortedVisible.map(n=>row(n,p.nodes.indexOf(n))).join('');
 const filtered=p.nodes.filter(n=>n.filtered);
 const filteredBlock=filtered.length?'<details class="subscription-filtered"><summary>Скрыто фильтрами · '+filtered.length+'</summary><table><tbody>'+filtered.map(n=>row(n,p.nodes.indexOf(n),true)).join('')+'</tbody></table></details>':'';
 const missing=(kind,items)=>!items||!items.length?'':'<div class="subscription-missing"><b>'+(kind==='picked'?'Ранее выбранные узлы отсутствуют':'Ранее исключённые узлы отсутствуют')+'</b>'+items.map((k,i)=>'<span>'+esc(k.name)+(k.nth?' · дубликат '+(k.nth+1):'')+' <button class="copy-btn" data-drop-missing="'+kind+':'+i+'">Забыть</button></span>').join('')+'</div>';
 const update=state.subscriptionTab==='update';
 return '<div class="subscription-backdrop" id="subscriptionBackdrop"><section class="subscription-modal" role="dialog" aria-modal="true" aria-label="Серверы и настройки подписки"><header class="subscription-header"><div><h2>Серверы: '+esc(p.profile_id)+'</h2><p>В пуле '+selected+' из '+visible.length+' · исключено вручную '+excluded+' · скрыто фильтрами '+filtered.length+'</p></div><button type="button" class="subscription-close" id="closeSubscription" aria-label="Закрыть">×</button></header>'+
 (p.observatoryError?'<p class="muted-note observatory-note">'+esc(p.observatoryError)+'</p>':'')+'<div class="subscription-toolbar"><input id="subscriptionSearch" type="search" placeholder="⌕ Поиск серверов…"><button type="button" class="button secondary" id="refreshSubscription">⇩ Обновить подписку</button><button type="button" class="button secondary" id="probeSubscription" '+(p.probing?'disabled':'')+'>↻ '+(p.probing?'Опрос…':'Опросить серверы')+'</button></div>'+
 '<div class="subscription-table-wrap"><table class="subscription-table"><thead><tr><th><label class="subscription-check"><input id="pickAllNodes" type="checkbox" '+(all?'checked':'')+'> '+(all?'Снять все':'Выделить все')+'</label></th><th colspan="2"><button type="button" class="subscription-sort" data-sub-sort="name">Имя'+sortMark('name')+'</button></th><th><button type="button" class="subscription-sort" data-sub-sort="echo">Пинг'+sortMark('echo')+'</button></th><th><button type="button" class="subscription-sort" data-sub-sort="delay">Задержка'+sortMark('delay')+'</button></th></tr><tr><th colspan="5"><label class="subscription-check offline-filter"><input id="excludeOffline" type="checkbox" '+(offlineAll?'checked':'')+' '+(!offline.length?'disabled':'')+'> offline <span class="muted">· исключить недоступные узлы ('+offline.length+')</span></label></th></tr></thead><tbody>'+(rows||'<tr><td colspan="5" class="muted">Подписка не содержит узлов</td></tr>')+'</tbody></table></div>'+filteredBlock+missing('picked',p.missing_picked)+missing('excluded',p.missing_excluded)+
 '<nav class="subscription-tabs"><button type="button" data-sub-tab="update" class="'+(update?'active':'')+'"><span class="subscription-status-light" aria-hidden="true"></span> Обновление</button><button type="button" data-sub-tab="filters" class="'+(!update?'active':'')+'"><span class="subscription-status-light" aria-hidden="true"></span> Фильтры</button></nav>'+
 (update?'<div class="subscription-settings"><label class="subscription-check"><input id="autoUpdateSubscription" type="checkbox" '+(p.auto_update_enabled?'checked':'')+' '+(!p.auto_update_available?'disabled':'')+'> Обновлять подписку автоматически</label><div class="subscription-interval"><span>Интервал:</span><input id="refreshHours" type="number" min="0" max="168" value="'+Math.floor((p.auto_update_interval||1440)/60)+'"><span>ч</span><input id="refreshMinutes" type="number" min="0" max="59" value="'+((p.auto_update_interval||1440)%60)+'"><span>м</span></div>'+(!p.auto_update_available?'<small class="muted">Автообновление доступно только для URL-подписок</small>':'')+'</div>':'<div class="subscription-filters"><div><label>Оставить только</label><textarea id="filterInclude" '+(!p.filter_available?'disabled':'')+' placeholder="LTE&#10;Germany">'+esc(p.filter_keep||'')+'</textarea></div><div><label>Исключить</label><textarea id="filterExclude" '+(!p.filter_available?'disabled':'')+' placeholder="Россия&#10;Russia">'+esc(p.filter_exclude||'')+'</textarea></div><button type="button" class="button secondary" id="applySubscriptionFilters" '+(!p.filter_available?'disabled':'')+'>Применить фильтры</button>'+(!p.filter_available?'<small class="muted">Фильтры применяются только к подпискам; прямые ссылки остаются без изменений</small>':'')+'</div>')+
 '<footer class="subscription-footer"><button type="button" class="button secondary" id="cancelSubscription">Отмена</button><button type="button" class="button primary" id="saveSubscription">Сохранить</button></footer></section></div>';
}
// Display flags only when the node name explicitly identifies a country.
function serverCountryFlag(name){
 const countries={"россия":"🇷🇺","russia":"🇷🇺","москва":"🇷🇺","moscow":"🇷🇺","германия":"🇩🇪","germany":"🇩🇪","швеция":"🇸🇪","sweden":"🇸🇪","латвия":"🇱🇻","latvia":"🇱🇻","эстония":"🇪🇪","estonia":"🇪🇪","польша":"🇵🇱","poland":"🇵🇱","финляндия":"🇫🇮","finland":"🇫🇮","нидерланды":"🇳🇱","netherlands":"🇳🇱","голландия":"🇳🇱","амстердам":"🇳🇱","франция":"🇫🇷","france":"🇫🇷","париж":"🇫🇷","испания":"🇪🇸","spain":"🇪🇸","италия":"🇮🇹","italy":"🇮🇹","турция":"🇹🇷","turkey":"🇹🇷","сша":"🇺🇸","usa":"🇺🇸","united states":"🇺🇸","япония":"🇯🇵","japan":"🇯🇵","великобритания":"🇬🇧","united kingdom":"🇬🇧","uk":"🇬🇧","сингапур":"🇸🇬","singapore":"🇸🇬","казахстан":"🇰🇿","kazakhstan":"🇰🇿","чехия":"🇨🇿","czechia":"🇨🇿","швейцария":"🇨🇭","switzerland":"🇨🇭","австрия":"🇦🇹","austria":"🇦🇹"};
 const words=String(name||'').toLowerCase().match(/[\p{L}]+/gu)||[];
 for(const [country,flag] of Object.entries(countries)){const tokens=country.split(' ');if(tokens.length===1?words.includes(country):String(name).toLowerCase().includes(country))return flag;}
 return '';
}
function updateObservatoryRows(p){document.querySelectorAll('.subscription-node-row[data-node-row]').forEach(row=>{const n=p.nodes[Number(row.dataset.nodeRow)];if(!n)return;const key=JSON.stringify(n.key),st=p.observatory?.[key],echo=p.echoes?.[key];const ping=echo?(echo.pending?'…':(echo.delay!==undefined?String(esc(echo.delay))+' ms':'N/A')):'—';const has=!!(st&&st.last_try_time),delay=st?(st.pending?'…':(has?(st.stale?'устарело':(st.alive?String(esc(st.delay_ms))+' ms':'offline')):'—')):'—';const pc=row.querySelector('.node-ping'),dc=row.querySelector('.node-delay');if(pc)pc.innerHTML=ping==='—'?'<span class="muted">—</span>':ping==='N/A'?'<span class="muted">N/A</span>':ping==='…'?'<span class="muted">…</span>':'<span class="good">'+ping+'</span>';if(dc)dc.innerHTML=delay==='offline'?'<span class="bad">● offline</span>':delay==='устарело'?'<span class="muted" title="Последнее измерение сохранено, но Xray не подтвердил его актуальность">устарело</span>':delay==='—'?'<span class="muted">—</span>':delay==='…'?'<span class="muted">…</span>':'<span class="good">'+delay+'</span>';});const note=document.querySelector('.observatory-note');if(note)note.textContent=p.observatoryError||'';}
function stopObservatoryPolling(){if(observatoryPollTimer!==null){clearTimeout(observatoryPollTimer);observatoryPollTimer=null;}}
function scheduleObservatoryPolling(profileID){stopObservatoryPolling();const poll=async()=>{const p=state.preview;if(!p||p.profile_id!==profileID)return;try{const obs=await api('/v1/observatory/status?profile_id='+encodeURIComponent(profileID));if(state.preview!==p)return;p.observatory=obs.statuses||{};p.observatoryError=obs.available?(obs.balancer_candidate_name?'Кандидат балансировщика: '+obs.balancer_candidate_name:''):(obs.error||'Результаты Observatory временно недоступны');updateObservatoryRows(p);}catch(e){if(state.preview===p){p.observatoryError='Не удалось получить состояние Observatory';render();}}if(state.preview===p)observatoryPollTimer=setTimeout(poll,5000);};observatoryPollTimer=setTimeout(poll,5000);}
function closeServerPicker(){stopObservatoryPolling();if(observatoryPingAbort){observatoryPingAbort.abort();observatoryPingAbort=null;}state.preview=null;render();}
async function openServerPicker(profileID){try{const data=await api('/v1/profiles/preview','POST',{profile_id:profileID});state.preview=data;state.preview.echoes={};state.subscriptionProfileID=profileID;state.subscriptionTab='update';state.page='network';try{const obs=await api('/v1/observatory/status?profile_id='+encodeURIComponent(profileID));state.preview.observatory=obs.statuses||{};state.preview.observatoryError=obs.available?(obs.balancer_candidate_name?'Кандидат балансировщика: '+obs.balancer_candidate_name:''):(obs.error||'Результаты Observatory временно недоступны');const off=state.preview.nodes.filter(n=>{const x=state.preview.observatory[JSON.stringify(n.key)];return x&&x.last_try_time&&!x.stale&&!x.alive;});state.preview.exclude_offline=off.length>0&&off.every(n=>n.excluded);}catch(e){state.preview.observatory={};state.preview.observatoryError='Результаты Observatory пока недоступны';}render();scheduleObservatoryPolling(profileID);}catch(err){toast(err.message,true);}}
function changePickMode(mode){if(!state.preview)return;const p=state.preview;if(mode==='manual'&&p.pick_mode!=='manual'){p.nodes.forEach(n=>{if(!n.filtered)n.picked=!n.excluded;});}if(mode==='auto'){p.nodes.forEach(n=>{if(!n.filtered)n.picked=!n.excluded;});p.missing_picked=[];}p.pick_mode=mode;render();}
function togglePreviewNode(index,field,checked){if(!state.preview||!state.preview.nodes[index])return;const node=state.preview.nodes[index];if(node.filtered)return;node[field]=checked;if(checked)node[field==='picked'?'excluded':'picked']=false;state.preview.pick_mode='manual';render();}
function dropMissingSelection(value){if(!state.preview)return;const [kind,indexText]=value.split(':');const index=Number(indexText);if(kind==='picked')state.preview.missing_picked.splice(index,1);else if(kind==='excluded')state.preview.missing_excluded.splice(index,1);render();}
function applySubscriptionFilters(){const p=state.preview;if(!p)return;const keep=String($('filterInclude')?.value??p.filter_keep??'');const exclude=String($('filterExclude')?.value??p.filter_exclude??'');const words=x=>x.replace(/\r\n/g,'\n').split('\n').map(v=>v.trim()).filter(v=>v&&!v.startsWith('#')).map(v=>v.toLowerCase());const k=words(keep),e=words(exclude);p.filter_keep=keep;p.filter_exclude=exclude;p.nodes.forEach(n=>{const name=n.name.toLowerCase();n.filtered=(k.length>0&&!k.some(w=>name.includes(w)))||e.some(w=>name.includes(w));});render();toast('Фильтры применены к списку; ручной выбор сохранён отдельно');}
async function saveServerSelection(){const p=state.preview;if(!p)return;if(observatoryPingAbort){observatoryPingAbort.abort();observatoryPingAbort=null;}const auto=$('autoUpdateSubscription')?.checked??!!p.auto_update_enabled;const hours=Number($('refreshHours')?.value??Math.floor((p.auto_update_interval||1440)/60)),minutes=Number($('refreshMinutes')?.value??((p.auto_update_interval||1440)%60));const interval=hours*60+minutes;if(!Number.isInteger(hours)||hours<0||hours>168||!Number.isInteger(minutes)||minutes<0||minutes>59||interval<5||interval>10080){toast('Интервал должен быть от 5 минут до 7 суток',true);return;}const keep=String($('filterInclude')?.value??p.filter_keep??''),excludeText=String($('filterExclude')?.value??p.filter_exclude??'');const filtered=n=>{const words=x=>x.replace(/\r\n/g,'\n').split('\n').map(v=>v.trim()).filter(v=>v&&!v.startsWith('#')).map(v=>v.toLowerCase());const k=words(keep),e=words(excludeText),name=n.name.toLowerCase();return (k.length>0&&!k.some(w=>name.includes(w)))||e.some(w=>name.includes(w));};const picked=(p.missing_picked||[]).concat(p.nodes.filter(n=>n.picked&&!n.excluded).map(n=>n.key));const excluded=(p.missing_excluded||[]).concat(p.nodes.filter(n=>n.excluded).map(n=>n.key));try{await api('/v1/profiles','PUT',{id:p.profile_id,filter_keep:keep,filter_exclude:excludeText,auto_update_enabled:!!auto,auto_update_interval:interval,pick_mode:'manual',picked,excluded});toast('Настройки подписки сохранены и конфигурация применена');stopObservatoryPolling();state.preview=null;await loadData();}catch(err){toast(err.message,true);}}
async function refreshSubscriptionNow(){try{await api('/v1/profiles/refresh','POST',{profile_id:state.subscriptionProfileID});toast('Подписка обновлена');await openServerPicker(state.subscriptionProfileID);}catch(err){toast(err.message,true);}}
async function probeSubscriptionNow(){const p=state.preview;if(!p||p.probing)return;p.probing=true;p.echoes={};p.nodes.filter(n=>!n.filtered&&!n.excluded&&(p.pick_mode!=='manual'||n.picked)).forEach(n=>{p.echoes[JSON.stringify(n.key)]={pending:true};});p.observatory={...(p.observatory||{})};p.nodes.filter(n=>!n.filtered&&!n.excluded&&(p.pick_mode!=='manual'||n.picked)).forEach(n=>{p.observatory[JSON.stringify(n.key)]={pending:true};});render();let streamError='';try{const controller=new AbortController();observatoryPingAbort=controller;const response=await fetch('/v1/profiles/ping?profile_id='+encodeURIComponent(p.profile_id),{method:'GET',credentials:'same-origin',headers:{Accept:'text/event-stream'},signal:controller.signal});if(!response.ok)throw new Error('HTTP '+response.status);if(!response.body)throw new Error('Потоковый ответ недоступен в этом браузере');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',done=false;while(!done){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);const line=block.split(/\r?\n/).find(x=>x.startsWith('data:'));if(!line)continue;const msg=JSON.parse(line.slice(5).trim());if(msg.links){p.echoes=Object.fromEntries(msg.links.map(k=>[k,{pending:true}]));}else if(msg.echo){p.echoes[msg.link]=msg.echo;}else if(msg.ping){p.observatory[msg.link]={alive:!!msg.ping.alive,delay_ms:msg.ping.delay,last_try_time:msg.ping.at};}if(msg.done){done=true;streamError=msg.error||'';}render();if(done)break;}}if(!done&&!streamError)streamError='Поток опроса завершился до получения итогового события';}catch(err){if(err.name!=='AbortError')streamError=err.message;}finally{if(observatoryPingAbort)observatoryPingAbort=null;p.probing=false;if(state.preview===p)render();if(streamError)toast(streamError,true);else if(state.preview===p)toast('Опрос серверов завершён');}}


function healthStateLabel(value){return ({healthy:"Норма",warning:"Предупреждение",degraded:"Проблема",checking:"Проверка",disabled:"Выключено",not_configured:"Не настроено"})[value]||value||"Нет данных";}
function healthMonitorCard(){const h=state.healthMonitor||{},checks=h.checks||[],metrics=h.metrics||{};return '<article class="card"><div class="section-title"><h2>Health Monitor</h2><span class="pill '+(h.status==="healthy"?"good":h.status==="degraded"?"bad":"")+'">'+esc(healthStateLabel(h.status))+'</span></div><div class="info-list">'+checks.map(c=>'<div class="info-row"><span>'+esc(c.name)+'</span><b>'+esc(healthStateLabel(c.state))+'</b></div>').join('')+'</div><div class="muted-note" style="margin-top:10px">Проверено: '+esc(formatTime(h.checked_at))+' · Диск свободно: '+(metrics.disk_free_bytes?esc((metrics.disk_free_bytes/1073741824).toFixed(2))+' ГБ':'—')+' · RAM доступно: '+(metrics.memory_available_bytes?esc((metrics.memory_available_bytes/1073741824).toFixed(2))+' ГБ':'—')+'</div><button class="button secondary" id="runHealthCheck" style="margin-top:12px">Проверить сейчас</button></article>';}
function eventJournal(){const items=state.events||[];return '<article class="card"><div class="section-title"><h2>Журнал событий</h2><button class="copy-btn" id="clearEvents" '+(!items.length?'disabled':'')+'>Очистить</button></div>'+(items.length?'<div class="info-list event-list">'+items.slice().reverse().map(e=>'<div class="info-row"><span><b>'+esc(e.component)+' · '+esc(e.type)+'</b><small>'+esc(formatTime(e.time))+'</small></span><span class="event-message">'+esc(e.message)+'</span></div>').join('')+'</div>':'<div class="empty">Событий пока нет</div>')+'<div class="muted-note" style="margin-top:10px">Хранится до 500 структурированных записей. Секреты подписок и содержимое конфигураций в журнал не записываются.</div></article>';}
function logsPage(){return '<div class="grid">'+healthMonitorCard()+'<div class="grid two-col"><article class="card"><div class="section-title"><h2>Состояние обновлений</h2><span class="pill">'+(state.refresh&&state.refresh.running?"Выполняется":"Ожидание")+'</span></div><div class="info-list"><div class="info-row"><span>Последняя попытка</span><b>'+esc(formatTime(state.refresh&&state.refresh.last_attempt))+'</b></div><div class="info-row"><span>Последний успех</span><b>'+esc(formatTime(state.refresh&&state.refresh.last_success))+'</b></div><div class="info-row"><span>Ошибки подряд</span><b>'+esc(state.refresh&&state.refresh.consecutive_failures||0)+'</b></div><div class="info-row"><span>Последняя ошибка</span><b>'+esc(state.refresh&&state.refresh.last_error||"—")+'</b></div></div></article><article class="card"><div class="section-title"><h2>Runtime</h2></div><div class="info-list"><div class="info-row"><span>Процесс</span><b>'+(state.runtime&&state.runtime.running?"Активен":"Остановлен")+'</b></div><div class="info-row"><span>Конфигурация</span><b>'+(state.runtime&&state.runtime.configured?"Подготовлена":"Отсутствует")+'</b></div></div><div class="muted-note" style="margin-top:12px">Журнал фиксирует события Core и не подменяет stdout/stderr самого процесса Xray.</div></article></div>'+eventJournal()+'</div>';}
function infoPage(){return '<div class="grid two-col"><article class="card"><div class="section-title"><h2>Система</h2><span class="tag">CORE</span></div><div class="info-list"><div class="info-row"><span>Продукт</span><b>HydraRoute Core</b></div><div class="info-row"><span>Сборка</span><b>Pre-release</b></div><div class="info-row"><span>Архитектура</span><b>Linux ARM64 / AMD64</b></div><div class="info-row"><span>Движок</span><b>Xray</b></div><div class="info-row"><span>Тема</span><b>Midnight + Violet</b></div></div></article><article class="card"><div class="section-title"><h2>Безопасность</h2></div><div class="info-list"><div class="info-row"><span>API bind</span><b>Loopback only</b></div><div class="info-row"><span>Общий SOCKS5</span><b>Loopback only</b></div><div class="info-row"><span>Маршруты ОС</span><b>Не изменяются</b></div><div class="info-row"><span>Firewall / DNS</span><b>Не изменяются</b></div><div class="info-row"><span>Хранилище профилей</span><b>Зашифровано</b></div></div></article></div>';}
function smartDNSUpstreamCards(){
 const cfg=state.smartDNS?.config||{},items=cfg.upstreams||[];
 if(!items.length)return '<div class="empty">Upstream-подключения пока не добавлены</div>';
 return items.map((u,i)=>'<div class="dns-server-card"><div style="min-width:0;flex:1"><b>'+esc(u.host)+'</b><div class="muted">'+esc(String(u.protocol||'DoH').toUpperCase())+' · '+esc(u.profile_id)+' · '+esc(u.bootstrap_ip||'Bootstrap не задан')+'</div><div class="muted">'+esc(u.path||'')+' '+Number(u.port||(u.protocol==='dot'?853:443))+'</div></div><div style="display:flex;gap:8px;align-items:center"><label class="checkline"><input type="checkbox" data-smartdns-upstream-toggle="'+i+'" '+(u.enabled?'checked':'')+'> Активен</label><button class="copy-btn" data-smartdns-upstream-remove="'+i+'">Удалить</button></div></div>').join('');
}
function smartDNSRuleCards(){
 const rules=state.smartDNS?.config?.rules||[];
 return rules.map((r,i)=>'<div class="dns-server-card"><div><b>'+esc(r.pattern)+'</b><div class="muted">'+esc(r.match_type)+' · '+esc(r.profile_id)+'</div></div><button class="copy-btn" data-smartdns-rule-remove="'+i+'">Удалить</button></div>').join('')||'<div class="empty">Правила доменной маршрутизации пока не добавлены</div>';
}
function smartDNSCard(){
 const sd=state.smartDNS||{},cfg=sd.config||{},status=sd.status||{},running=!!status.running,enabled=!!cfg.enabled;
 const label=running?'Работает':enabled?'Подготовлена':'Выключена';
 return '<div class="dns-stack"><article class="card dns-panel"><div class="dns-service-head"><div><div class="section-title"><h2>SmartDNS sidecar</h2><span class="pill '+(running?'good':'')+'">'+label+'</span></div><p class="muted">Отдельный DNS-движок с DoH/DoT upstream через выбранные SOCKS5-профили Xray</p></div><button class="button secondary" id="smartDNSAction">'+(running?'Остановить':'Запустить')+'</button></div><div class="form-grid"><div class="field full"><label class="checkline"><input id="smartDNSEnabled" type="checkbox" '+(enabled?'checked':'')+'> Разрешить запуск SmartDNS</label></div><div class="field"><label for="smartDNSListenPort">Локальный порт</label><input id="smartDNSListenPort" type="number" min="1025" max="65535" value="'+Number(cfg.listen_port||5354)+'"><small class="muted">SmartDNS слушает только 127.0.0.1</small></div><div class="field"><label for="smartDNSCacheSize">Размер кэша</label><input id="smartDNSCacheSize" type="number" min="0" max="1000000" value="'+Number(cfg.cache_size||0)+'"></div></div><div class="form-actions"><button class="button primary" id="smartDNSSave">Сохранить и подготовить конфигурацию</button></div>'+(sd.error?'<div class="muted-note">'+esc(sd.error)+'</div>':'')+'</article><article class="card dns-panel"><div class="section-title"><div><h2>Профильные upstream DNS</h2><small class="muted">Каждый сервер жёстко привязан к выбранному профилю SOCKS5</small></div><button class="network-add" id="smartDNSAddUpstream">＋ Добавить upstream</button></div><div class="dns-server-list">'+smartDNSUpstreamCards()+'</div></article><article class="card dns-panel"><div class="section-title"><div><h2>Правила доменной маршрутизации</h2><small class="muted">Точное имя или доменный суффикс → профиль</small></div><button class="network-add" id="smartDNSAddRule">＋ Добавить правило</button></div><div class="dns-server-list">'+smartDNSRuleCards()+'</div></article><div class="muted-note">SmartDNS не запускается автоматически после загрузки конфигурации. Сначала сохраните параметры, затем нажмите «Запустить». Системный DNS, маршруты и firewall не изменяются. Managed и пользовательские block/allow списки обрабатываются Core DNS до пересылки запроса. SmartDNS отвечает только за выбор профильного upstream.</div></div>';
}
function dnsPage(){
 const tabs=[['core','Общие'],['service','Служба DNS'],['smartdns','SmartDNS'],['servers','Серверы'],['blocking','Блокировка'],['stats','Статистика']];
 const d=state.dns||{},status=state.dnsStatus||{},st=state.dnsStats||{};let body='';
 if(state.dnsTab==='service'){
  body='<div class="dns-stack">'+
   '<article class="card dns-panel"><div class="dns-service-head"><div class="dns-service-title"><button class="runtime-toggle '+(status.running?'on':'')+'" id="dnsToggle" aria-label="Включить или выключить DNS"><span></span></button><div><b>Служба DNS</b><div class="muted">'+(status.running?'Служба принимает DNS-запросы':'Служба остановлена')+'</div></div><span class="pill '+(status.running?'good':'')+'">'+(status.running?'Работает':'Выключена')+'</span></div><button class="network-icon-btn" id="dnsRefresh" title="Обновить состояние">↻</button></div><div class="dns-metrics"><span>Прослушивание: <b>'+esc(status.listen||d.listen||'127.0.0.1')+':'+esc(status.port||d.port||5353)+'</b></span><span>Запросов с запуска: <b>'+Number(st.total||0).toLocaleString('ru-RU')+'</b></span></div></article>'+
   '<article class="card dns-panel"><div class="section-title"><h2>Параметры службы</h2><span class="pill">Core DNS</span></div><div class="form-grid"><div class="field"><label>Адрес прослушивания</label><input id="dnsListen" value="'+esc(d.listen||'127.0.0.1')+'" readonly><small class="muted">Только localhost — удалённый доступ через отдельный защищённый шлюз</small></div><div class="field"><label>Порт DNS</label><input id="dnsPort" type="number" min="1024" max="65535" value="'+Number(d.port||5353)+'"></div><div class="field full"><label>Режим выбора upstream DNS</label><select id="dnsDefaultProvider"><option value="" '+(!d.default_provider?'selected':'')+'>Автоматически: DNS активного DHCP-подключения</option>'+(d.servers||[]).map(x=>'<option value="'+esc(x.name)+'" '+(d.default_provider===x.name?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select><small class="muted">Если автоопределение выключено или DHCP DNS недоступен, используется выбранный сервер. При пустом выборе — первый включённый сервер.</small></div><div class="field full"><label class="checkline"><input id="dnsAutoProvider" type="checkbox" '+(d.auto_provider!==false?'checked':'')+'> Автоматически определять DNS активного подключения</label></div></div><div class="muted-note" style="margin-top:14px">HydraRoute Core не переписывает системный resolv.conf, настройки Keenetic или таблицу маршрутизации. Клиенты пока должны обращаться к DNS-службе явно: 127.0.0.1:'+Number(d.port||5353)+'.</div><div class="form-actions"><button class="button primary" id="dnsSave">Сохранить параметры</button></div></article>'+
   '<article class="card dns-panel"><div class="section-title"><h2>DNS активного подключения <span class="help-tip" tabindex="0" data-tip="Показываются только DNS-адреса, полученные через DHCP на интерфейсе активного маршрута. Если DHCP сообщает адрес роутера, это будет адрес роутера, а не обязательно upstream DNS провайдера.">!</span></h2><button class="copy-btn" id="dnsDetect">↻ Определить</button></div><div class="muted-note">'+esc(d.provider_name||'DNS-провайдер не определён')+'<br>'+esc((d.provider_servers||[]).join(', ')||'DHCP DNS не обнаружен')+'</div></article></div>';
 }else if(state.dnsTab==='smartdns'){
  body=smartDNSCard();
 }else if(state.dnsTab==='servers'){
  body='<article class="card dns-panel"><div class="section-title"><div><h2>Серверы DNS</h2><small class="muted">Upstream-серверы и порядок выбора</small></div><button class="network-add" id="dnsAddServer">＋ Добавить сервер</button></div><div class="dns-server-list">'+dnsServerCards()+'</div></article>';
 }else if(state.dnsTab==='blocking'){
  body='<div class="dns-stack"><article class="card dns-panel"><div class="dns-service-head"><div><h2>Фильтрация доменов</h2><p class="muted">Блокировка по пользовательским правилам DNS</p></div><label class="checkline"><input id="dnsBlockEnabled" type="checkbox" '+(d.blocking_enabled?'checked':'')+'> Включить фильтрацию</label></div><div class="muted-note">Собственные правила и загруженные списки применяются локальной DNS-службой Core. Allow-исключения из списков имеют приоритет над блокировкой; ошибка обновления не удаляет последнюю рабочую версию. Системный DNS и маршруты не меняются.</div></article>'+
   '<article class="card dns-panel"><div class="section-title"><div><h2>Списки фильтрации</h2><small class="muted">'+Number(state.dnsBlocklists?.blocked?.length||0)+' заблокировано · '+Number(state.dnsBlocklists?.allowed?.length||0)+' исключений</small></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><button class="button secondary" id="dnsRefreshBlocklists">↻ Обновить все</button><button class="network-add" id="dnsAddBlocklist">＋ Добавить источник</button></div></div><div class="form-grid" style="margin:12px 0"><div class="field"><label><input id="dnsBlockAutoUpdate" type="checkbox" '+((state.dnsBlocklists?.settings?.autoUpdate??false)?'checked':'')+'> Ежедневное автоматическое обновление</label></div><div class="field"><label for="dnsBlockUpdateTime">Время обновления</label><input id="dnsBlockUpdateTime" type="time" value="'+esc(state.dnsBlocklists?.settings?.updateTime||'04:30')+'"></div><div class="field"><label for="dnsBlockIface">Интерфейс загрузки (необязательно)</label><input id="dnsBlockIface" type="text" maxlength="15" placeholder="Пусто — автоматически" value="'+esc(state.dnsBlocklists?.settings?.iface||'')+'"></div><div class="field"><button class="button secondary" id="dnsBlockSettingsSave">Сохранить расписание</button></div></div><div class="muted-note">Обновление выполняется ежедневно по местному времени сервера. Можно закрепить загрузку за сетевым интерфейсом, например eth0; пустое поле использует системную маршрутизацию.</div><div id="dnsBlocklists">'+dnsBlocklistCards()+'</div></article>'+
   '<article class="card dns-panel"><div class="section-title"><div><h2>Собственные списки блокировки и исключений</h2><small class="muted">По одному домену на строку; поддерживаются обычные домены и ABP-формат</small></div><button class="button secondary" id="dnsBlockCustomSave">Сохранить списки</button></div><div class="form-grid"><div class="field"><label for="dnsCustomBlock">Блокировать</label><textarea id="dnsCustomBlock" rows="7" placeholder="ads.example.com&#10;||tracker.example^">'+esc((state.dnsBlocklists?.custom_block||[]).join('\n'))+'</textarea></div><div class="field"><label for="dnsCustomAllow">Разрешить</label><textarea id="dnsCustomAllow" rows="7" placeholder="safe.example.com&#10;@@||trusted.example^">'+esc((state.dnsBlocklists?.custom_allow||[]).join('\n'))+'</textarea></div></div></article>'+
   '<article class="card dns-panel"><div class="section-title"><div><h2>Пользовательские правила</h2><small class="muted">Дополнительные точечные правила DNS</small></div><button class="network-add" id="dnsAddBlockRule">＋ Добавить правило</button></div><div id="dnsBlockRules">'+dnsBlockRuleCards()+'</div></article>'+
   '<article class="card dns-panel"><div class="section-title"><h2>Проверка домена</h2></div><div class="dns-check-row"><input id="dnsCheckDomain" placeholder="например, ads.example.com"><button class="button secondary" id="dnsCheck">Проверить</button></div><small class="muted">Проверка выполняется через настроенные upstream DNS-серверы HydraRoute Core.</small><div id="dnsCheckResult"></div></article></div>';
 }else if(state.dnsTab==='stats'){
  body='<div class="grid stats-grid"><article class="card stat-card"><div class="stat-label">ЗАПРОСЫ</div><div class="stat-value">'+Number(st.total||0).toLocaleString('ru-RU')+'</div><div class="stat-hint">С момента запуска службы</div></article><article class="card stat-card"><div class="stat-label">ЗАБЛОКИРОВАНО</div><div class="stat-value">'+Number(st.blocked||0).toLocaleString('ru-RU')+'</div><div class="stat-hint">По правилам и спискам</div></article><article class="card stat-card"><div class="stat-label">УСПЕШНО</div><div class="stat-value">'+Number(st.success||0).toLocaleString('ru-RU')+'</div><div class="stat-hint">Получены ответы upstream/Hosts</div></article><article class="card stat-card"><div class="stat-label">ОШИБКИ</div><div class="stat-value">'+Number(st.errors||0).toLocaleString('ru-RU')+'</div><div class="stat-hint">Ошибки разрешения запросов</div></article></div>'+
   '<article class="card dns-panel"><div class="section-title"><div><h2>Статистика DNS</h2><small class="muted">Счётчики текущего процесса службы</small></div><button class="copy-btn" id="dnsStatsRefresh">↻ Обновить</button></div><div class="info-list"><div class="info-row"><span>Среднее время обработки</span><b>'+Number(st.avg_latency_ms||0)+' мс</b></div><div class="info-row"><span>Служба</span><b>'+(status.running?'Работает':'Остановлена')+'</b></div><div class="info-row"><span>Адрес и порт</span><b>'+esc(status.listen||d.listen||'127.0.0.1')+':'+Number(status.port||d.port||5353)+'</b></div><div class="info-row"><span>Выбор upstream</span><b>'+esc(d.auto_provider!==false?'Автоопределение DHCP':(d.default_provider||'Первый активный сервер'))+'</b></div><div class="info-row"><span>Активный DHCP DNS</span><b>'+esc((d.provider_servers||[]).join(', ')||'Не определён')+'</b></div></div><div class="muted-note" style="margin-top:14px">Кэш DNS, графики по времени и журнал отдельных запросов пока не реализованы. Здесь показаны только реальные счётчики текущего процесса; после перезапуска службы они обнуляются.</div></article>';
 }else{
  body='<div class="dns-stack"><article class="card dns-panel"><div class="section-title"><h2>DNS-серверы <span class="help-tip" tabindex="0" data-tip="Список upstream DNS-серверов. Выбор основного сервера и включение/отключение узлов настраиваются во вкладке «Серверы».">!</span></h2><span class="pill">'+(d.servers||[]).filter(x=>x.enabled).length+' активно</span></div><div id="dnsCoreServers">'+dnsServerCards()+'</div><button class="network-add" id="dnsAddServer">＋ Сервер</button></article><article class="card dns-panel"><div class="section-title"><h2>DNS провайдера <span class="help-tip" tabindex="0" data-tip="Автоматическое определение DNS, полученного по DHCP на интерфейсе активного маршрута. Адрес роутера не означает, что это DNS оператора напрямую.">!</span></h2><span class="pill">'+(d.provider_servers||[]).length+' адресов</span></div><div class="dns-provider-row"><div><b>Определение DNS активного подключения</b><p class="muted">DHCP DNS на интерфейсе с default route</p></div><label class="checkline"><input id="dnsAutoProvider" type="checkbox" '+(d.auto_provider!==false?'checked':'')+'> Авто</label></div><div class="muted-note">'+esc(d.provider_name||'DNS-провайдер не определён')+' · '+esc((d.provider_servers||[]).join(', ')||'Нет обнаруженных адресов')+'</div></article><article class="card dns-panel"><div class="section-title"><h2>Переопределение доменных имён (Hosts) <span class="help-tip" tabindex="0" data-tip="Локальные записи «имя → IP-адрес». Они обслуживаются службой DNS HydraRoute Core и не записываются в Keenetic или системный hosts-файл.">!</span></h2><span class="pill">Локальные записи</span></div><div id="dnsHostsList">'+dnsHostCards()+'</div><button class="network-add" id="dnsAddHost">＋ Запись</button></article></div>';
 }
 return '<div class="dns-workspace"><div class="dns-tabs">'+tabs.map(t=>'<button class="dns-tab '+(state.dnsTab===t[0]?'active':'')+'" data-dns-tab="'+t[0]+'">'+t[1]+'</button>').join('')+'</div><div class="dns-page-actions"><span class="pill '+(status.running?'good':'')+'">'+(status.running?'DNS активен':'DNS остановлен')+'</span><button class="copy-btn" id="dnsRefresh">↻ Обновить</button></div>'+body+'</div>';
}
function dnsProviderOptions(selected){const providers=[['','Автоматический DNS оператора'],['yandex','Yandex DNS · Basic'],['adguard','AdGuard DNS · Default'],['cloudflare','Cloudflare · 1.1.1.1'],['quad9','Quad9 · Standard'],['google','Google DNS'],['custom','Пользовательский']];return providers.map(x=>'<option value="'+x[0]+'" '+(x[0]===selected?'selected':'')+'>'+x[1]+'</option>').join('');}
function dnsServerCards(){const a=state.dns.servers||[];return a.length?a.map((x,i)=>'<div class="dns-server-card dns-upstream-card"><div class="dns-upstream-main"><div class="dns-upstream-heading"><b>'+esc(x.name)+'</b><span class="pill '+(x.enabled?'good':'')+'">'+(x.enabled?'Включён':'Отключён')+'</span></div><div class="muted">'+esc(x.protocol)+' · '+esc(x.address)+'</div><div class="dns-upstream-meta">'+(state.dns.default_provider===x.name?'<span class="pill">Основной</span>':'')+(x.latency_ms?'<span class="pill">'+Number(x.latency_ms)+' мс</span>':'<span class="pill">Не проверен</span>')+'</div></div><div class="dns-upstream-actions"><label class="checkline"><input type="checkbox" data-dns-server-enabled="'+i+'" '+(x.enabled?'checked':'')+'> Активен</label><button class="copy-btn" data-dns-edit-server="'+i+'" title="Изменить">✎</button><button class="copy-btn" data-dns-del-server="'+i+'" title="Удалить">×</button></div></div>').join(''):'<div class="empty">DNS-серверы пока не добавлены</div>'; }
function dnsServerRows(){return (state.dns.servers||[]).map((s,i)=>'<tr><td><b>'+esc(s.name)+'</b></td><td>'+esc(s.protocol)+'</td><td>'+esc(s.address)+'</td><td>'+esc(s.features||'—')+'</td><td>'+esc(s.latency_ms?s.latency_ms+' мс':'—')+'</td><td><button class="copy-btn" data-dns-edit-server="'+i+'">✎</button></td></tr>').join('')||'<tr><td colspan="6">DNS-серверы пока не добавлены</td></tr>';}
function dnsHostCards(){return (state.dns.hosts||[]).map((h,i)=>'<div class="dns-server-card"><div><b>'+esc(h.domain)+'</b><div class="muted">'+esc(h.address)+'</div></div><button class="copy-btn" data-dns-del-host="'+i+'">Удалить</button></div>').join('')||'<div class="muted-note">Пользовательских Hosts-записей нет</div>';}
function dnsRuleProviderCards(){return (state.dns.rule_providers||[]).map(x=>'<div class="dns-server-card"><b>'+esc(x.name)+'</b><span>'+esc(x.provider)+'</span><span class="pill">'+esc(x.scope)+'</span></div>').join('')||'<div class="muted-note">Переопределения для правил пока не настроены</div>';}
function dnsBlocklistCards(){
 const sources=state.dnsBlocklists?.sources||[];
 if(state.dnsBlocklists?.error)return '<div class="muted-note">'+esc(state.dnsBlocklists.error)+'</div>';
 if(!sources.length)return '<div class="empty">Источников нет — выберите готовый список или добавьте свой публичный HTTP(S)-URL</div>';
 return sources.map(s=>{
  const missing=state.dnsBlocklists?.missing?.[s.id]||[];const removed=(s.removed||[]).map(x=>'<span class="pill">'+esc(x.entry)+(missing.includes(x.entry)?' · нет в источнике':'')+' <button type="button" class="copy-btn" data-dns-blocklist-restore="'+esc(s.id)+'" data-domain="'+esc(x.entry)+'">Вернуть</button></span>').join(' ');
  const error=s.error?'<div class="muted-note">'+esc(s.error)+' · последняя рабочая версия сохранена</div>':'';
  const updated=s.updated?'Обновлено '+esc(formatTime(s.updated)):'Ещё не загружен';
  return '<div class="dns-server-card"><div style="min-width:0;flex:1"><b>'+esc(s.name)+'</b><div class="muted">'+esc(s.url)+'</div><div class="muted">'+Number(s.count||0)+' заблокировано · '+Number(s.allow||0)+' исключений · '+Number(s.dropped||0)+' отброшено · '+updated+'</div>'+error+(removed?'<div class="muted-note"><b>Исключённые домены:</b> '+removed+'</div>':'')+'</div><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><label class="checkline"><input type="checkbox" data-dns-blocklist-toggle="'+esc(s.id)+'" '+(s.enabled?'checked':'')+'> Активен</label><button type="button" class="copy-btn" data-dns-blocklist-refresh="'+esc(s.id)+'" title="Обновить">↻</button><button type="button" class="copy-btn" data-dns-blocklist-remove="'+esc(s.id)+'">Исключить домен</button><button type="button" class="copy-btn" data-dns-blocklist-delete="'+esc(s.id)+'">Удалить</button></div></div>';
 }).join('');
}
function dnsBlockRuleCards(){return (state.dns.rules||[]).map((x,i)=>'<div class="dns-server-card"><div><b>'+esc(x.domain)+'</b><div class="muted">'+esc(x.action)+'</div></div><button class="copy-btn" data-dns-del-rule="'+i+'">Удалить</button></div>').join('')||'<div class="muted-note">Собственных правил пока нет</div>';}
async function loadDNS(){try{const [d,lists,smart]=await Promise.all([api('/v1/dns'),api('/v1/dns/blocklists').catch(e=>({sources:[],blocked:[],allowed:[],error:e.message})),api('/v1/dns/smartdns').catch(e=>({config:state.smartDNS?.config||{enabled:false,listen_host:'127.0.0.1',listen_port:5354,cache_size:0,upstreams:[],rules:[],domain_sets:[]},status:{enabled:false,running:false},error:e.message}))]);state.dns=d.config||state.dns;state.dns.servers=state.dns.servers||[];state.dns.hosts=state.dns.hosts||[];state.dns.blocklists=state.dns.blocklists||[];state.dns.rules=state.dns.rules||[];state.dnsStatus=d.status||{};state.dnsStats=d.stats||{};state.dnsBlocklists=lists||{sources:[],blocked:[],allowed:[]};state.smartDNS=smart||state.smartDNS;}catch(e){state.dnsStatus={running:false};}}
async function saveSmartDNS(){
 const cfg=JSON.parse(JSON.stringify(state.smartDNS?.config||{}));
 cfg.enabled=$('smartDNSEnabled')?.checked??!!cfg.enabled;
 cfg.listen_host='127.0.0.1';
 cfg.listen_port=Number($('smartDNSListenPort')?.value||cfg.listen_port||5354);
 cfg.cache_size=Number($('smartDNSCacheSize')?.value||cfg.cache_size||0);
 cfg.upstreams=cfg.upstreams||[];cfg.rules=cfg.rules||[];cfg.domain_sets=cfg.domain_sets||[];
 try{state.smartDNS=await api('/v1/dns/smartdns','PUT',cfg);toast('SmartDNS-конфигурация сохранена и подготовлена');render();}catch(e){toast(e.message,true);}
}
async function smartDNSAction(){
 const action=state.smartDNS?.status?.running?'stop':'start';
 try{state.smartDNS=await api('/v1/dns/smartdns/'+action,'POST',{});toast(action==='start'?'SmartDNS запущен':'SmartDNS остановлен');render();}catch(e){toast(e.message,true);await loadDNS();render();}
}
function smartDNSAddUpstream(){
 const available=(state.profiles||[]).filter(p=>p.enabled);
 if(!available.length){toast('Сначала создайте и включите Xray-профиль',true);return;}
 const profileID=prompt('ID профиля Xray для SOCKS5:\n'+available.map(p=>(p.name||p.id)+' — '+p.id).join('\n'),available[0].id);
 if(!profileID)return;
 if(!available.some(p=>p.id===profileID.trim())){toast('Указанный профиль не найден или выключен',true);return;}
 const protocol=(prompt('Протокол: DoH или DoT','DoH')||'').trim().toLowerCase();
 if(!['doh','dot'].includes(protocol)){toast('Поддерживаются только DoH и DoT',true);return;}
 const host=prompt('DNS hostname','cloudflare-dns.com');if(!host)return;
 const bootstrap=prompt('Bootstrap IP','1.1.1.1');if(!bootstrap)return;
 const portText=prompt('Порт',protocol==='dot'?'853':'443');if(!portText)return;
 const port=Number(portText);if(!Number.isInteger(port)||port<1||port>65535){toast('Некорректный порт',true);return;}
 const path=protocol==='doh'?(prompt('DoH path','/dns-query')||'/dns-query'):'';
 const cfg=state.smartDNS.config;cfg.upstreams=cfg.upstreams||[];
 cfg.upstreams.push({id:'smartdns-upstream-'+Date.now(),profile_id:profileID.trim(),protocol,host:host.trim(),port,path,bootstrap_ip:bootstrap.trim(),enabled:true});
 render();toast('Upstream добавлен в черновик — нажмите «Сохранить»');
}
function smartDNSAddRule(){
 const available=(state.profiles||[]).filter(p=>p.enabled);
 if(!available.length){toast('Нет включённых Xray-профилей',true);return;}
 const pattern=prompt('Домен или суффикс, например example.com');if(!pattern)return;
 const match=(prompt('Тип совпадения: exact или suffix','suffix')||'suffix').trim().toLowerCase();
 if(!['exact','suffix'].includes(match)){toast('Тип должен быть exact или suffix',true);return;}
 const profileID=prompt('ID профиля:\n'+available.map(p=>(p.name||p.id)+' — '+p.id).join('\n'),available[0].id);
 if(!profileID)return;
 if(!available.some(p=>p.id===profileID.trim())){toast('Профиль не найден или выключен',true);return;}
 const cfg=state.smartDNS.config;cfg.rules=cfg.rules||[];
 cfg.rules.push({id:'smartdns-rule-'+Date.now(),match_type:match,pattern:pattern.trim(),profile_id:profileID.trim(),enabled:true});
 render();toast('Правило добавлено в черновик — нажмите «Сохранить»');
}
async function removeSmartDNSUpstream(index){const cfg=state.smartDNS.config;cfg.upstreams.splice(index,1);await saveSmartDNS();}
async function removeSmartDNSRule(index){const cfg=state.smartDNS.config;cfg.rules.splice(index,1);await saveSmartDNS();}
async function saveDNS(){try{const d=state.dns;d.listen=$('dnsListen')?.value||d.listen;d.port=Number($('dnsPort')?.value||d.port);d.default_provider=$('dnsDefaultProvider')?.value??d.default_provider;d.auto_provider=$('dnsAutoProvider')?.checked??d.auto_provider;d.blocking_enabled=$('dnsBlockEnabled')?.checked??d.blocking_enabled;await api('/v1/dns','PUT',d);toast('Настройки DNS сохранены');await loadDNS();render();}catch(e){toast(e.message,true);}}
async function dnsToggle(){try{await api('/v1/dns/service','POST',{action:state.dnsStatus?.running?'stop':'start'});await loadDNS();render();toast('Состояние DNS-службы обновлено');}catch(e){toast(e.message,true);}}
async function dnsEditServer(index){const old=Number.isInteger(index)?state.dns.servers[index]:null;const name=prompt('Название DNS-сервера',old?.name||'');if(!name)return;const protocol=prompt('Протокол: Do53, DoT или DoH',old?.protocol||'DoH');if(!protocol)return;const address=prompt('Адрес сервера (IP:порт или URL)',old?.address||'');if(!address)return;const item={...(old||{}),name:name.trim(),protocol:protocol.toUpperCase(),address:address.trim(),enabled:old?old.enabled!==false:true};if(old)state.dns.servers[index]=item;else state.dns.servers.push(item);await saveDNS();}
async function dnsDeleteServer(index){const x=state.dns.servers[index];if(!x||!confirm('Удалить DNS-сервер «'+x.name+'»?'))return;state.dns.servers.splice(index,1);if(state.dns.default_provider===x.name)state.dns.default_provider='';await saveDNS();}
async function dnsAddHost(){const domain=prompt('Домен');if(!domain)return;const address=prompt('IP-адрес');if(!address)return;state.dns.hosts.push({domain,address});await saveDNS();}
async function dnsAddBlocklist(){let name,url;try{const catalog=await api('/v1/dns/blocklists/catalog');const presets=catalog.presets||[];const menu=presets.map((p,i)=>(i+1)+'. '+p.name).join('\\n')+'\\n0. Свой URL';const choice=prompt('Выберите готовый DNS-список или добавьте свой:\\n'+menu,'1');if(choice===null)return;if(choice.trim()==='0'){name=prompt('Название списка');if(!name)return;url=prompt('Публичный URL HTTP(S)-списка');if(!url)return;}else{const index=Number(choice)-1;if(!Number.isInteger(index)||index<0||index>=presets.length){toast('Неверный номер списка',true);return;}name=presets[index].name;url=presets[index].url;}const created=await api('/v1/dns/blocklists','POST',{name:name.trim(),url:url.trim(),enabled:true});try{await api('/v1/dns/blocklists/'+encodeURIComponent(created.source.id)+'/refresh','POST',{});toast('Источник добавлен и загружен');}catch(err){toast('Источник сохранён, обновление не удалось: '+err.message,true);}}catch(err){toast(err.message,true);}await loadDNS();render();}
async function dnsBlockCustomSave(){
 try{
  const block=$('dnsCustomBlock')?.value||'';
  const allow=$('dnsCustomAllow')?.value||'';
  await api('/v1/dns/blocklists/custom','PUT',{block,allow});
  toast('Собственные списки сохранены');
  await loadDNS();render();
 }catch(e){toast(e.message,true);}
}
async function dnsBlocklistSaveSettings(){const body={autoUpdate:$('dnsBlockAutoUpdate')?.checked||false,updateTime:$('dnsBlockUpdateTime')?.value||'04:30',iface:($('dnsBlockIface')?.value||'').trim()};try{const result=await api('/v1/dns/blocklists/settings','PUT',body);state.dnsBlocklists.settings=result.settings;toast(result.settings.autoUpdate?'Ежедневное обновление сохранено':'Автоматическое обновление выключено');await loadDNS();render();}catch(err){toast(err.message,true);}}
async function dnsBlocklistRefreshAll(){try{const result=await api('/v1/dns/blocklists/_refresh','POST',{});const failures=result.failures||[];toast(failures.length?'Обновление завершено с ошибками: '+failures[0]:'Все списки обновлены',failures.length>0);}catch(err){toast(err.message,true);}await loadDNS();render();}
async function dnsBlocklistRefresh(id){try{await api('/v1/dns/blocklists/'+encodeURIComponent(id)+'/refresh','POST',{});toast('Список обновлён');}catch(err){toast(err.message,true);}await loadDNS();render();}
async function dnsBlocklistToggle(id,enabled){try{await api('/v1/dns/blocklists/'+encodeURIComponent(id),'PATCH',{enabled});await loadDNS();render();}catch(err){toast(err.message,true);}}
async function dnsBlocklistDelete(id){const source=(state.dnsBlocklists?.sources||[]).find(x=>x.id===id);if(!source||!confirm('Удалить источник «'+source.name+'»?'))return;try{await api('/v1/dns/blocklists/'+encodeURIComponent(id),'DELETE');toast('Источник удалён');await loadDNS();render();}catch(err){toast(err.message,true);}}
async function dnsBlocklistRemoveDomain(id){const domain=prompt('Домен для исключения из этого источника');if(!domain)return;try{await api('/v1/dns/blocklists/'+encodeURIComponent(id)+'/remove','POST',{domain:domain.trim()});toast('Домен исключён из источника');await loadDNS();render();}catch(err){toast(err.message,true);}}
async function dnsBlocklistRestoreDomain(id,domain){try{await api('/v1/dns/blocklists/'+encodeURIComponent(id)+'/restore','POST',{domain});toast('Домен восстановлен');await loadDNS();render();}catch(err){toast(err.message,true);}}
async function dnsAddBlockRule(){const domain=prompt('Домен или маска');if(!domain)return;const action=prompt('Действие: block или allow','block');state.dns.rules.push({domain,action:action==='allow'?'allow':'block'});await saveDNS();}
async function dnsCheck(){const domain=$('dnsCheckDomain')?.value.trim();if(!domain)return;try{const r=await api('/v1/dns/check','POST',{domain});$('dnsCheckResult').innerHTML='<div class="muted-note">'+esc(r.status||'Проверено')+' · '+esc((r.addresses||[]).join(', '))+'</div>';}catch(e){toast(e.message,true);}}
function bindDNS(){
 document.querySelectorAll('[data-dns-tab]').forEach(b=>b.onclick=()=>{state.dnsTab=b.dataset.dnsTab;render();});
 $('dnsRefresh')?.addEventListener('click',async()=>{await loadDNS();render();});$('dnsStatsRefresh')?.addEventListener('click',async()=>{await loadDNS();render();});$('dnsDetect')?.addEventListener('click',async()=>{await loadDNS();render();toast('Данные DHCP DNS обновлены');});
 $('dnsToggle')?.addEventListener('click',dnsToggle);$('dnsSave')?.addEventListener('click',saveDNS);
 $('smartDNSSave')?.addEventListener('click',saveSmartDNS);$('smartDNSAction')?.addEventListener('click',smartDNSAction);$('smartDNSAddUpstream')?.addEventListener('click',smartDNSAddUpstream);$('smartDNSAddRule')?.addEventListener('click',smartDNSAddRule);
 document.querySelectorAll('[data-smartdns-upstream-toggle]').forEach(b=>b.onchange=()=>{const u=state.smartDNS.config.upstreams[Number(b.dataset.smartdnsUpstreamToggle)];if(u){u.enabled=b.checked;saveSmartDNS();}});
 document.querySelectorAll('[data-smartdns-upstream-remove]').forEach(b=>b.onclick=()=>removeSmartDNSUpstream(Number(b.dataset.smartdnsUpstreamRemove)));
 document.querySelectorAll('[data-smartdns-rule-remove]').forEach(b=>b.onclick=()=>removeSmartDNSRule(Number(b.dataset.smartdnsRuleRemove)));
 $('dnsAddServer')?.addEventListener('click',()=>dnsEditServer(null));$('dnsAddHost')?.addEventListener('click',dnsAddHost);$('dnsAddBlocklist')?.addEventListener('click',dnsAddBlocklist);$('dnsBlockCustomSave')?.addEventListener('click',dnsBlockCustomSave);$('dnsRefreshBlocklists')?.addEventListener('click',dnsBlocklistRefreshAll);$('dnsBlockSettingsSave')?.addEventListener('click',dnsBlocklistSaveSettings);$('dnsAddBlockRule')?.addEventListener('click',dnsAddBlockRule);$('dnsCheck')?.addEventListener('click',dnsCheck);
 $('dnsAutoProvider')?.addEventListener('change',e=>{state.dns.auto_provider=e.target.checked;saveDNS();});$('dnsBlockEnabled')?.addEventListener('change',e=>{state.dns.blocking_enabled=e.target.checked;saveDNS();});
 document.querySelectorAll('[data-dns-edit-server]').forEach(b=>b.onclick=()=>dnsEditServer(Number(b.dataset.dnsEditServer)));
 document.querySelectorAll('[data-dns-del-server]').forEach(b=>b.onclick=()=>dnsDeleteServer(Number(b.dataset.dnsDelServer)));
 document.querySelectorAll('[data-dns-server-enabled]').forEach(b=>b.onchange=()=>{const x=state.dns.servers[Number(b.dataset.dnsServerEnabled)];if(x)x.enabled=b.checked;saveDNS();});
 document.querySelectorAll('[data-dns-del-host]').forEach(b=>b.onclick=()=>{state.dns.hosts.splice(+b.dataset.dnsDelHost,1);saveDNS();});
  document.querySelectorAll('[data-dns-blocklist-toggle]').forEach(b=>b.onchange=()=>dnsBlocklistToggle(b.dataset.dnsBlocklistToggle,b.checked));
  document.querySelectorAll('[data-dns-blocklist-refresh]').forEach(b=>b.onclick=()=>dnsBlocklistRefresh(b.dataset.dnsBlocklistRefresh));
  document.querySelectorAll('[data-dns-blocklist-remove]').forEach(b=>b.onclick=()=>dnsBlocklistRemoveDomain(b.dataset.dnsBlocklistRemove));
  document.querySelectorAll('[data-dns-blocklist-delete]').forEach(b=>b.onclick=()=>dnsBlocklistDelete(b.dataset.dnsBlocklistDelete));
  document.querySelectorAll('[data-dns-blocklist-restore]').forEach(b=>b.onclick=()=>dnsBlocklistRestoreDomain(b.dataset.dnsBlocklistRestore,b.dataset.domain));
  document.querySelectorAll('[data-dns-del-rule]').forEach(b=>b.onclick=()=>{state.dns.rules.splice(+b.dataset.dnsDelRule,1);saveDNS();});
 $('dnsSearch')?.addEventListener('input',e=>{document.querySelectorAll('.dns-table tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});
}

function l7SettingsCard(){const s=state.l7Settings||{enabled:false,http:true,tls:true,quic:true};return '<article class="card"><div class="section-title"><h2>L7-анализ</h2><span class="tag">CORE SOCKS5</span></div><div class="field"><label><input id="l7Enabled" type="checkbox" '+(s.enabled?'checked':'')+'> Включить анализ HTTP Host, TLS SNI и QUIC SNI</label></div><div class="form-grid"><div class="field"><label><input id="l7HTTP" type="checkbox" '+(s.http?'checked':'')+'> HTTP Host · порт 80</label></div><div class="field"><label><input id="l7TLS" type="checkbox" '+(s.tls?'checked':'')+'> TLS SNI · порт 443</label></div><div class="field"><label><input id="l7QUIC" type="checkbox" '+(s.quic?'checked':'')+'> QUIC SNI · UDP/443</label></div><div class="form-actions field full"><button class="button primary" id="saveL7Settings">Сохранить L7</button></div></div><div class="muted-note" style="margin-top:10px">Работает только с трафиком, который явно входит в SOCKS5-подключения HydraRoute Core. Не перехватывает транзитный LAN/VPN-трафик, не использует NFLOG и не меняет firewall. Сохранённые настройки применяются при следующей сборке Xray-конфигурации.</div></article>';}

function healthSettingsCard(){const s=state.healthSettings||{enabled:true,interval_seconds:30,timeout_seconds:4,fail_threshold:2,recover_threshold:2};return '<article class="card"><div class="section-title"><h2>Health Monitor</h2><span class="tag">LOCAL CHECKS</span></div><div class="field"><label><input id="healthEnabled" type="checkbox" '+(s.enabled?'checked':'')+'> Включить автоматический мониторинг</label></div><div class="form-grid"><div class="field"><label for="healthInterval">Интервал, секунд</label><input id="healthInterval" type="number" min="5" max="3600" value="'+s.interval_seconds+'"></div><div class="field"><label for="healthTimeout">Тайм-аут, секунд</label><input id="healthTimeout" type="number" min="1" max="30" value="'+s.timeout_seconds+'"></div><div class="field"><label for="healthFailThreshold">Порог ошибок подряд</label><input id="healthFailThreshold" type="number" min="1" max="10" value="'+s.fail_threshold+'"></div><div class="field"><label for="healthRecoverThreshold">Порог восстановления</label><input id="healthRecoverThreshold" type="number" min="1" max="10" value="'+s.recover_threshold+'"></div><div class="form-actions field full"><button class="button primary" id="saveHealthSettings">Сохранить мониторинг</button></div></div><div class="muted-note" style="margin-top:10px">Проверяет локальный Xray API, DNS, GeoData, Watchlist, свободное место и память. Не меняет маршруты, firewall или системный DNS.</div></article>';}
function settingsPage(){const v=Number(state.observatorySettings.probe_interval_seconds)||120;return '<div class="grid"><article class="card"><div class="section-title"><h2>Observatory</h2><span class="tag">XRAY</span></div><div class="form-grid"><div class="field"><label for="observatoryProbeInterval">Интервал опроса серверов (секунды)</label><input id="observatoryProbeInterval" type="number" min="5" max="3600" step="1" value="'+v+'"></div><div class="field"><label>Допустимое значение</label><div class="muted-note">5–3600 секунд. Настройка общая для всех профилей.</div></div><div class="form-actions field full"><button class="button primary" id="saveObservatorySettings">Сохранить интервал</button></div></div><div class="muted-note" style="margin-top:10px">Xray опрашивает все выбранные узлы параллельно; интервал задаёт паузу между полными циклами опроса. Если Xray уже запущен, изменение применяется сразу с безопасным перезапуском и откатом при ошибке; если конфигурация ещё не подготовлена — при следующей сборке.</div></article>'+healthSettingsCard()+l7SettingsCard()+'<div class="section-title"><h2>Управление и применение</h2></div>'+deployPage()+'<div class="section-title" style="margin-top:10px"><h2>Состояние и журнал</h2></div>'+logsPage()+'</div>';}
async function loadObservatorySettings(){try{state.observatorySettings=await api('/v1/observatory/settings');}catch(e){toast('Не удалось загрузить настройки Observatory',true);}}
async function saveObservatorySettings(){const input=$('observatoryProbeInterval');if(!input)return;const value=Number(input.value);if(!Number.isInteger(value)||value<5||value>3600){toast('Интервал должен быть целым числом от 5 до 3600 секунд',true);return;}try{const result=await api('/v1/observatory/settings','PUT',{probe_interval_seconds:value});state.observatorySettings=result;const applies=result.applies||'';toast(applies==='active Xray runtime restarted'?'Интервал применён, Xray перезапущен':applies==='prepared Xray configuration updated'?'Интервал применён к конфигурации Xray':'Интервал сохранён для следующей сборки');render();}catch(e){toast(e.message,true);}}
async function saveHealthSettings(){const body={enabled:$('healthEnabled')?.checked||false,interval_seconds:Number($('healthInterval')?.value),timeout_seconds:Number($('healthTimeout')?.value),fail_threshold:Number($('healthFailThreshold')?.value),recover_threshold:Number($('healthRecoverThreshold')?.value)};try{state.healthSettings=await api('/v1/health/settings','PUT',body);toast('Настройки Health Monitor сохранены');render();}catch(err){toast(err.message,true);}}
async function runHealthCheckNow(){try{state.healthMonitor=await api('/v1/health/check','POST',{});const data=await api('/v1/events?limit=50').catch(()=>({events:[]}));state.events=data.events||[];render();toast('Проверка Health Monitor завершена');}catch(err){toast(err.message,true);}}
async function clearEvents(){if(!confirm('Очистить журнал событий?'))return;try{await api('/v1/events','DELETE',{});state.events=[];render();toast('Журнал событий очищен');}catch(err){toast(err.message,true);}}
async function saveL7Settings(){const body={enabled:$("l7Enabled")?.checked||false,http:$("l7HTTP")?.checked||false,tls:$("l7TLS")?.checked||false,quic:$("l7QUIC")?.checked||false};if(body.enabled&&!body.http&&!body.tls&&!body.quic){toast("Выберите хотя бы один протокол L7",true);return;}try{state.l7Settings=await api("/v1/l7/settings","PUT",body);toast("Настройки L7 сохранены — применятся при следующей сборке");render();}catch(err){toast(err.message,true);}}
async function logout(){try{await fetch("/auth/logout",{method:"POST",credentials:"same-origin"});}finally{location.replace("/login");}}
function render(){const c=$("pageContent");if(state.page==="rules")c.innerHTML=rulesPage();else if(state.page==="network")c.innerHTML=tunnelPage();else if(state.page==="dns")c.innerHTML=dnsPage();else if(state.page==="hydra")c.innerHTML=connectPage();else if(state.page==="settings")c.innerHTML=settingsPage();else if(state.page==="servers")c.innerHTML=serverPickerPage();else c.innerHTML=infoPage();bindPage();}
async function submitGeoDataUpdate(e){e.preventDefault();const form=e.currentTarget;const action=e.submitter?.dataset.geodataAction||'preflight';if(action==='activate'&&!confirm('Обновление перезапустит Xray. Продолжить?'))return;const f=new FormData(form);const body={geoip:{url:String(f.get('geoip_url')).trim(),sha256:String(f.get('geoip_sha256')).trim()},geosite:{url:String(f.get('geosite_url')).trim(),sha256:String(f.get('geosite_sha256')).trim()}};const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await api('/v1/geodata/'+action,'POST',body);toast(action==='preflight'?'Проверка GeoData пройдена, базы не применены':'GeoData обновлены');await loadData();}catch(err){toast('GeoData: '+err.message,true);buttons.forEach(b=>b.disabled=false);}}
function bindPage(){if(state.page==="dns")bindDNS();const geoForm=$("geodataUpdateForm");if(geoForm)geoForm.onsubmit=submitGeoDataUpdate;const healthSave=$("saveHealthSettings");if(healthSave)healthSave.onclick=saveHealthSettings;const healthCheck=$("runHealthCheck");if(healthCheck)healthCheck.onclick=runHealthCheckNow;const eventsClear=$("clearEvents");if(eventsClear)eventsClear.onclick=clearEvents;const obsSave=$("saveObservatorySettings");if(obsSave)obsSave.onclick=saveObservatorySettings;const l7Save=$("saveL7Settings");if(l7Save)l7Save.onclick=saveL7Settings;document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>setPage(b.dataset.page));document.querySelectorAll("[data-copy]").forEach(b=>b.onclick=()=>copyText(b.dataset.copy));document.querySelectorAll("[data-delete-profile]").forEach(b=>b.onclick=()=>deleteProfile(b.dataset.deleteProfile));document.querySelectorAll("[data-preview-servers]").forEach(b=>b.onclick=()=>openServerPicker(b.dataset.previewServers));document.querySelectorAll("[data-drop-missing]").forEach(b=>b.onclick=()=>dropMissingSelection(b.dataset.dropMissing));document.querySelectorAll("[data-move-up]").forEach(b=>b.onclick=()=>moveRule(Number(b.dataset.moveUp),-1));document.querySelectorAll("[data-move-down]").forEach(b=>b.onclick=()=>moveRule(Number(b.dataset.moveDown),1));document.querySelectorAll("[data-drag-rule]").forEach(handle=>{handle.addEventListener("dragstart",e=>{state.dragRuleIndex=Number(handle.dataset.dragRule);e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",String(state.dragRuleIndex));});handle.addEventListener("dragend",()=>{state.dragRuleIndex=null;document.querySelectorAll(".rule-card.drag-over").forEach(el=>el.classList.remove("drag-over"));});let pointerStart=null;handle.addEventListener("pointerdown",e=>{if(e.pointerType==="mouse")return;pointerStart=Number(handle.dataset.dragRule);state.dragRuleIndex=pointerStart;handle.setPointerCapture(e.pointerId);});handle.addEventListener("pointermove",e=>{if(pointerStart===null)return;const under=document.elementFromPoint(e.clientX,e.clientY);const card=under&&under.closest(".rule-card[data-rule]");document.querySelectorAll(".rule-card.drag-over").forEach(el=>el.classList.toggle("drag-over",el===card));});handle.addEventListener("pointerup",e=>{if(pointerStart===null)return;const under=document.elementFromPoint(e.clientX,e.clientY);const card=under&&under.closest(".rule-card[data-rule]");const from=pointerStart,to=card?Number(card.dataset.rule):from;pointerStart=null;state.dragRuleIndex=null;if(to!==from&&Number.isInteger(to)){const moved=state.routing.rules.splice(from,1)[0];state.routing.rules.splice(to,0,moved);render();toast("Порядок изменён — нажмите «Сохранить»");}else document.querySelectorAll(".rule-card.drag-over").forEach(el=>el.classList.remove("drag-over"));});handle.addEventListener("pointercancel",()=>{pointerStart=null;state.dragRuleIndex=null;document.querySelectorAll(".rule-card.drag-over").forEach(el=>el.classList.remove("drag-over"));});});document.querySelectorAll(".rule-card[data-rule]").forEach(card=>{card.addEventListener("dragover",e=>{if(state.dragRuleIndex===undefined||state.dragRuleIndex===null)return;e.preventDefault();e.dataTransfer.dropEffect="move";card.classList.add("drag-over");});card.addEventListener("dragleave",()=>card.classList.remove("drag-over"));card.addEventListener("drop",e=>{e.preventDefault();card.classList.remove("drag-over");const from=state.dragRuleIndex,to=Number(card.dataset.rule);if(from===undefined||from===null||from===to)return;const moved=state.routing.rules.splice(from,1)[0];state.routing.rules.splice(to,0,moved);state.dragRuleIndex=null;render();toast("Порядок изменён — нажмите «Сохранить»");});});document.querySelectorAll("[data-runtime]").forEach(b=>b.onclick=()=>runtimeAction(b.dataset.runtime));document.querySelectorAll("[data-refresh]").forEach(b=>b.onclick=refreshProfiles);document.querySelectorAll(".pick-node").forEach(b=>b.onchange=()=>togglePreviewNode(Number(b.dataset.index),"picked",b.checked));document.querySelectorAll(".exclude-node").forEach(b=>b.onchange=()=>togglePreviewNode(Number(b.dataset.index),"excluded",b.checked));const pm=$("pickMode");if(pm)pm.onchange=()=>changePickMode(pm.value);const ss=$("saveSelection");if(ss)ss.onclick=saveServerSelection;const closeSub=$("closeSubscription"),cancelSub=$("cancelSubscription");if(closeSub)closeSub.onclick=closeServerPicker;if(cancelSub)cancelSub.onclick=closeServerPicker;const saveSub=$("saveSubscription");if(saveSub)saveSub.onclick=saveServerSelection;const pickAll=$("pickAllNodes");if(pickAll)pickAll.onchange=()=>{const p=state.preview;if(!p)return;p.pick_mode='manual';p.nodes.forEach(n=>{if(n.filtered)return;n.picked=pickAll.checked;n.excluded=!pickAll.checked;});p.missing_picked=[];p.missing_excluded=[];render();};const offlineBox=$("excludeOffline");if(offlineBox)offlineBox.onchange=()=>{const p=state.preview;if(!p)return;p.nodes.forEach(n=>{if(n.filtered)return;const st=p.observatory?.[JSON.stringify(n.key)];if(st&&st.last_try_time&&!st.stale&&!st.alive){n.excluded=offlineBox.checked;n.picked=!offlineBox.checked;}});p.pick_mode='manual';p.exclude_offline=offlineBox.checked;render();};const searchSub=$("subscriptionSearch");if(searchSub)searchSub.oninput=()=>{const q=searchSub.value.toLowerCase();document.querySelectorAll('.subscription-node-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));};document.querySelectorAll('[data-sub-tab]').forEach(b=>b.onclick=()=>{state.subscriptionTab=b.dataset.subTab;render();});document.querySelectorAll('[data-sub-sort]').forEach(b=>b.onclick=()=>{const p=state.preview;if(!p)return;const key=b.dataset.subSort;p.sort=p.sort&&p.sort.key===key?{key,asc:!p.sort.asc}:{key,asc:true};render();});const filterApply=$("applySubscriptionFilters");if(filterApply)filterApply.onclick=applySubscriptionFilters;const refreshSub=$("refreshSubscription");if(refreshSub)refreshSub.onclick=refreshSubscriptionNow;const probeSub=$("probeSubscription");if(probeSub)probeSub.onclick=probeSubscriptionNow;const pf=$("profileForm");if(pf)pf.onsubmit=saveProfile;const rf=$("ruleEditorForm");if(rf)rf.onsubmit=saveRuleEditor;const actionSelect=$("ruleEditorAction"),profileField=$("ruleProfileField");if(actionSelect&&profileField){const syncProfileField=()=>{profileField.hidden=actionSelect.value!=="profile";};actionSelect.onchange=syncProfileField;syncProfileField();}const add=$("addRuleButton");if(add)add.onclick=()=>openRuleEditor(null,"profile");const exportRules=$("exportRules");if(exportRules)exportRules.onclick=()=>{const data=JSON.stringify({version:1,rules:state.routing.rules||[]},null,2);const blob=new Blob([data],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="hydraroute-rules.json";a.click();URL.revokeObjectURL(url);toast("Правила экспортированы");};const importRules=$("importRules"),importFile=$("importRulesFile");if(importRules&&importFile){importRules.onclick=()=>importFile.click();importFile.onchange=async()=>{const file=importFile.files&&importFile.files[0];if(!file)return;try{const data=JSON.parse(await file.text());const rules=Array.isArray(data)?data:data.rules;if(!Array.isArray(rules))throw new Error("В файле нет массива rules");if(!rules.every(r=>r&&typeof r.name==="string"&&Array.isArray(r.values)&&["profile","direct","block"].includes(r.action)))throw new Error("Формат правил не распознан");state.routing.rules=rules.map(r=>({...r,id:r.id||("rule-"+Date.now()+Math.random())}));render();toast("Правила импортированы — нажмите «Сохранить»");}catch(err){toast("Ошибка импорта: "+err.message,true);}finally{importFile.value="";}};}const rulesHelp=$("rulesHelp");if(rulesHelp)rulesHelp.onclick=()=>alert("Правила обрабатываются сверху вниз: первое совпадение определяет маршрут. Перетаскивайте правило за маркер ⠿. Переключатель рядом с названием отключает правило. Изменения применяются после нажатия «Сохранить».");const ex=$("exportRulesButton");if(ex)ex.onclick=exportRules;const im=$("importRulesButton"),fi=$("importRulesFile");if(im&&fi){im.onclick=()=>fi.click();fi.onchange=()=>{importRulesFile(fi.files&&fi.files[0]);fi.value="";};}const hp=$("rulesHelpButton");if(hp)hp.onclick=()=>alert("Правила обрабатываются сверху вниз: первое совпадение имеет приоритет. Добавьте правило для маршрута через профиль или DirectRoute для прямого выхода. Перетаскивайте строки за маркер ⠿. После изменений нажмите «Сохранить».");const cancel=$("cancelRuleEditor");if(cancel)cancel.onclick=()=>{state.ruleEditorOpen=false;state.editingRuleIndex=null;render();};document.querySelectorAll("[data-edit-rule]").forEach(b=>b.onclick=()=>openRuleEditor(Number(b.dataset.editRule)));document.querySelectorAll("[data-duplicate-rule]").forEach(b=>b.onclick=()=>duplicateRule(Number(b.dataset.duplicateRule)));document.querySelectorAll("[data-rule-enabled]").forEach(b=>b.onchange=()=>{const i=Number(b.dataset.ruleEnabled);if(state.routing.rules[i])state.routing.rules[i].enabled=b.checked;});const sr=$("saveRouting");if(sr)sr.onclick=saveRouting;document.querySelectorAll("[data-network-tab]").forEach(b=>b.onclick=()=>{state.networkTab=b.dataset.networkTab;render();});const openConnection=$("openConnectionModal");if(openConnection)openConnection.onclick=openConnectionModal;document.querySelectorAll("[data-profile-toggle]").forEach(b=>b.onclick=()=>{const p=state.profiles.find(x=>x.id===b.dataset.profileToggle);if(p)toggleProfile(p.id,!p.enabled);});document.querySelectorAll("[data-connection-menu]").forEach(b=>b.onclick=()=>openConnectionSettingsMenu(b.dataset.connectionMenu,b));document.querySelectorAll("[data-profile-settings]").forEach(b=>b.onclick=()=>openProfileSettings(b.dataset.profileSettings));document.querySelectorAll("[data-profile-test]").forEach(b=>b.onclick=()=>testProfile(b.dataset.profileTest));document.querySelectorAll(".remove-rule").forEach(b=>b.onclick=()=>{state.routing.rules.splice(Number(b.dataset.index),1);render();});const exitButton=document.querySelector("#logoutButton");if(exitButton)exitButton.onclick=logout;}
async function saveProfile(e){e.preventDefault();const f=new FormData(e.target);const body={id:f.get("id"),source_id:f.get("source_id"),enabled:f.get("enabled")==="on",port:Number(f.get("port")),strategy:f.get("strategy"),links:String(f.get("links")).split(/\r?\n/).map(x=>x.trim()).filter(Boolean)};try{await api("/v1/profiles","POST",body);toast("Профиль сохранён");await loadData();setPage("hydra");}catch(err){toast(err.message,true);}}
function moveRule(index,delta){const next=index+delta;if(next<0||next>=state.routing.rules.length)return;const item=state.routing.rules[index];state.routing.rules[index]=state.routing.rules[next];state.routing.rules[next]=item;render();}
async function deleteProfile(id){if(!confirm("Удалить профиль "+id+"? Сначала удалите правила, которые на него ссылаются."))return;try{await api("/v1/profiles","DELETE",{id:id});toast("Профиль удалён");await loadData();}catch(err){toast(err.message,true);}}
function openRuleEditor(index,action){state.ruleEditorOpen=true;state.editingRuleIndex=Number.isInteger(index)?index:null;state.ruleEditorAction=action||((state.editingRuleIndex!==null&&state.routing.rules[state.editingRuleIndex])?state.routing.rules[state.editingRuleIndex].action:"profile");render();}
function saveRuleEditor(e){e.preventDefault();const f=new FormData(e.target);const values=String(f.get("values")).split(/[\r\n,]+/).map(x=>x.trim()).filter(Boolean);if(!values.length){toast("Добавьте хотя бы одно значение",true);return;}const action=f.get("action"),profile=e.target.querySelector(".rule-profile");const rule={id:"rule-"+Date.now(),name:String(f.get("name")).trim(),enabled:true,match_type:f.get("match_type"),values,action,profile_id:action==="profile"?(profile?profile.value:""):""};if(state.editingRuleIndex!==null){const old=state.routing.rules[state.editingRuleIndex];rule.id=old.id;rule.enabled=old.enabled;state.routing.rules[state.editingRuleIndex]=rule;}else state.routing.rules.push(rule);state.ruleEditorOpen=false;state.editingRuleIndex=null;render();toast("Правило подготовлено — нажмите «Сохранить изменения»");}
function duplicateRule(index){const source=state.routing.rules[index];if(!source)return;const copy=JSON.parse(JSON.stringify(source));copy.id="rule-"+Date.now();copy.name=(source.name||"Правило")+" — копия";state.routing.rules.splice(index+1,0,copy);state.editingRuleIndex=index+1;state.ruleEditorOpen=true;render();toast("Копия создана — проверьте параметры и сохраните");}
async function saveRouting(){const r=state.routing;if(state.page==="network"){r.enabled=$("routingEnabled").checked;r.listen=$("routingListen").value.trim();r.port=Number($("routingPort").value);r.default_action=$("defaultAction").value;r.default_profile_id=r.default_action==="profile"?$("defaultProfile").value:"";}else if(state.page==="rules"){r.rules=state.routing.rules;}try{await api("/v1/routing","PUT",r);toast("Настройки маршрутизации сохранены и применены");await loadData();setPage(state.page);}catch(err){toast(err.message,true);}}
async function runtimeAction(action){try{await api("/v1/runtime","POST",{action:action});toast(action==="start"?"Xray запущен":"Xray остановлен");await loadData();}catch(err){toast(err.message,true);}}
async function refreshProfiles(){try{await api("/v1/profiles/refresh","POST",{});toast("Профили обновлены, конфигурация подготовлена");await loadData();}catch(err){toast(err.message,true);}}
async function loadData(){try{const results=await Promise.all([api("/healthz"),api("/v1/runtime"),api("/v1/profiles"),api("/v1/routing"),api("/v1/refresh/status"),api("/v1/observatory/settings"),api("/v1/geodata/status"),api("/v1/l7/settings"),api("/v1/watchlist/status"),api("/v1/health/monitor").catch(()=>null),api("/v1/health/settings").catch(()=>null),api("/v1/events?limit=50").catch(()=>({events:[]}))]);state.health=results[0];state.runtime=results[1];state.profiles=results[2].profiles||[];state.routing=results[3].routing||state.routing;if(!state.routing.rules)state.routing.rules=[];state.configured=!!results[3].configured;state.refresh=results[4];state.observatorySettings=results[5];state.geodata=results[6];state.l7Settings=results[7];state.watchlist=results[8];state.healthMonitor=results[9];state.healthSettings=results[10]||state.healthSettings;state.events=results[11].events||[];if(state.page==="dns")await loadDNS();$("connectionText").textContent="API подключён";$("connectionText").parentElement.classList.add("online");const running=!!state.runtime.running;$("runtimeDot").className="status-dot"+(running?" online":"");$("runtimeLabel").textContent=running?"Xray работает":state.runtime.configured?"Готов к запуску":"Runtime не настроен";$("runtimeSub").textContent=running?"Процесс активен":state.profiles.length+" профилей";render();}catch(err){$("connectionText").textContent="API недоступен";$("connectionText").parentElement.classList.remove("online");$("pageContent").innerHTML='<div class="empty">Не удалось загрузить данные API: '+esc(err.message)+'</div>';}}
function theme(){const t=localStorage.getItem("hr-theme")||"dark";document.documentElement.dataset.theme=t==="light"?"light":"dark";$("themeToggle").textContent=t==="light"?"☾":"☼";}
document.addEventListener("DOMContentLoaded",()=>{theme();$("themeToggle").onclick=()=>{const t=document.documentElement.dataset.theme==="light"?"dark":"light";localStorage.setItem("hr-theme",t);theme();};$("menuToggle").onclick=()=>$("sidebar").classList.toggle("open");$("refreshButton").onclick=loadData;const logout=$("logoutButton");if(logout)logout.onclick=async()=>{try{await fetch("/auth/logout",{method:"POST",credentials:"same-origin"});}finally{location.replace("/login");}};document.querySelectorAll(".nav-item").forEach(b=>b.onclick=()=>setPage(b.dataset.page));loadData();});
})();